import { PlaneTakeoff, PlaneLanding, Loader2, CircleCheck, RotateCcw, TriangleAlert, Radio, GitMerge, GitPullRequest, FileWarning, Copy, Check } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import type { LandingState, LandingClass, TipShape } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';

export interface StagedLandingControlProps {
  /** The server-derived landing state — the control renders whatever phase this carries (dumb UI). */
  landingState: LandingState;
  /** An action is in flight (a reconcile/restore POST is pending or its run is streaming). */
  busy?: boolean;
  /** Start / re-run the reconcile ladder ("Prepare to land" / "Prepare again"). */
  onPrepare: () => void;
  /**
   * Land main to the tip: `ff-only` is the verified staged terminal; `merge` is the
   * secondary, explicitly-UNVERIFIED merge-commit terminal (bypasses the reconcile
   * + verify rung). Mirrors the island's delivery `onLand(method)`.
   */
  onLand: (method: 'ff-only' | 'merge') => void;
  /** Raise a PR — the secondary, unverified terminal that hands off to review. Absent ⇒ the secondary terminals are not offered. */
  onRaise?: () => void;
  /** Reset the branch to its pre-reconcile backup ("Restore pre-rebase"); offered while `canRestore`. */
  onRestore?: () => void;
  /** Open the live reconcile run stream in the island terminal (the `preparing` / `failed` click-through). */
  onOpenStream?: (runId: string) => void;
  /** Live reconcile phases while `preparing`, streamed into the log. */
  landLog?: readonly string[];
  /**
   * The reconcile run's raw output text (build/test stdout + error lines). Rendered
   * inline in `preparing` (live) and `failed` (the failing step / error), so a
   * failure shows WHY without leaving the strip.
   */
  runOutput?: string;
  /** The worktree branch — keys the `/merge <branch>` conflict hand-off (t3). */
  branch?: string;
}

/** Honest probe copy for the difficulty a prepare will face — before/independent of any reconcile. */
function probeCopy(probeClass: LandingClass): string {
  switch (probeClass) {
    case 'clean-ff':
      return 'fast-forward · clean';
    case 'clean-rebase':
      return 'rebase needed · ~clean';
    case 'recipe-covered':
      return 'rebase needed · conflicts, recipe-covered';
    case 'semantic':
      return 'rebase needed · semantic conflicts likely';
    case 'unknown':
      return 'landing difficulty unknown';
  }
}

/** The token that tints the probe pill by how much a prepare will fight. */
function probeTone(probeClass: LandingClass): string {
  switch (probeClass) {
    case 'clean-ff':
      return '--color-done';
    case 'semantic':
      return '--color-warn';
    case 'clean-rebase':
    case 'recipe-covered':
    case 'unknown':
      return '--color-blue';
  }
}

/** The ff land copy, honest about the tip SHAPE — an ff-merge-node carries a merge commit. */
function landCopy(tipShape?: TipShape): { label: string; detail: string; mergeNode: boolean } {
  if (tipShape === 'ff-merge-node') {
    return {
      label: 'Land (ff) · carries a merge commit',
      detail: 'The branch merged main in — land as-is, or rebase to a linear tip first.',
      mergeNode: true,
    };
  }
  return {
    label: 'Land (ff)',
    detail: tipShape === 'ff-linear' ? 'Linear history — no merge node.' : 'Fast-forward main to this tip.',
    mergeNode: false,
  };
}

/** Honest residual-conflict count label (`undefined` count ⇒ the reconcile record carried no file list). */
function conflictCountLabel(count: number | undefined): string {
  if (count === undefined) return 'conflicts need you';
  return count === 1 ? '1 conflict needs you' : `${count} conflicts need you`;
}

/** A small tinted status pill: glyph + label, tinted by a CSS colour token. */
function StatusPill({ varName, icon, children, pulse }: { varName: string; icon: ReactNode; children: ReactNode; pulse?: boolean }) {
  return (
    <span
      className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold"
      style={{ color: `var(${varName})`, background: `color-mix(in oklab, var(${varName}) 14%, transparent)` }}
    >
      <span className={cn('inline-flex', pulse && 'animate-pulse')}>{icon}</span>
      {children}
    </span>
  );
}

/**
 * The primary staged action button — a full-width action card (glyph + label +
 * detail). `active:scale-[0.96]` gives the press a tactile feel; the transition is
 * property-specific (never `transition: all`). The inner radius is one step under
 * the section's cards for a concentric fit.
 */
function ActionButton({
  onClick,
  disabled,
  icon,
  label,
  detail,
  tone = '--color-blue',
  variant = 'solid',
}: {
  onClick: () => void;
  disabled?: boolean;
  icon: ReactNode;
  label: string;
  detail?: string;
  tone?: string;
  variant?: 'solid' | 'ghost';
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={cn(
        'flex w-full flex-col gap-1 rounded-xl border p-3 text-left',
        'transition-[transform,background-color,border-color] duration-150 active:scale-[0.96]',
        disabled && 'cursor-not-allowed opacity-60 active:scale-100',
      )}
      style={
        variant === 'solid'
          ? {
              borderColor: `color-mix(in oklab, var(${tone}) 45%, transparent)`,
              background: `color-mix(in oklab, var(${tone}) 14%, transparent)`,
            }
          : { borderColor: 'var(--color-border)', background: 'transparent' }
      }
    >
      <span className="flex items-center gap-2 text-sm font-semibold text-foreground">
        <span className="shrink-0" style={{ color: `var(${tone})` }}>{icon}</span>
        <span className="text-balance">{label}</span>
      </span>
      {detail && <span className="pretty text-xs leading-snug text-muted-foreground">{detail}</span>}
    </button>
  );
}

/** Cap the rendered output — the failing step is at the END, so we keep the TAIL. */
const RUN_OUTPUT_TAIL_LINES = 200;

/**
 * The reconcile run's raw output — build/test stdout and error lines (e.g.
 * `spawn turbo ENOENT`). The failing step is at the END of the output, so we render
 * the TAIL (last {@link RUN_OUTPUT_TAIL_LINES} lines, capping a huge log) AND scroll
 * the box to the bottom on every update, so the error is what you land on rather than
 * stranded below the fold. Trailing blank lines are trimmed so it never opens empty.
 */
function RunOutputLog({ output, tone = '--color-border' }: { output: string; tone?: string }) {
  const ref = useRef<HTMLPreElement>(null);
  const tail = output.replace(/\s+$/, '').split('\n').slice(-RUN_OUTPUT_TAIL_LINES).join('\n');
  // Pin to the bottom whenever the output grows — the newest line is the interesting
  // one (live progress, or the failure). A native overflow box would otherwise sit at
  // the top. jsdom has no layout so this no-ops in tests; the tail cap keeps the error
  // in the DOM regardless.
  useEffect(() => {
    const el = ref.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [tail]);
  if (tail.length === 0) return null;
  return (
    <pre
      ref={ref}
      role="log"
      aria-live="polite"
      aria-label="Reconcile run output"
      className="mono max-h-40 overflow-y-auto whitespace-pre-wrap break-words rounded-lg border p-2 text-[11px] leading-relaxed text-muted-foreground"
      style={{ borderColor: `var(${tone})`, background: 'var(--color-muted)' }}
    >
      {tail}
    </pre>
  );
}

/** A small, subordinate land terminal (merge commit / raise PR) — visually secondary to the primary staged action. */
function SecondaryTerminal({ icon, label, onClick, disabled }: { icon: ReactNode; label: string; onClick: () => void; disabled?: boolean }) {
  return (
    <button
      type="button"
      onClick={onClick}
      disabled={disabled}
      className={cn(
        'inline-flex flex-1 items-center justify-center gap-1.5 rounded-lg border border-border px-3 py-2 text-xs font-medium text-muted-foreground',
        'transition-[transform,background-color,border-color,color] duration-150 active:scale-[0.96]',
        'hover:border-foreground/20 hover:bg-foreground/[0.03] hover:text-foreground',
        'disabled:opacity-60 disabled:active:scale-100',
      )}
    >
      {icon}
      {label}
    </button>
  );
}

/** A copyable one-line command chip — shows the command and a copy button with brief "Copied" feedback. */
function CopyCommand({ command, label }: { command: string; label: string }) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  // Clear the pending reset on unmount — a refetch resolving the conflicts phase
  // within the 2s window must not setCopied on an unmounted component.
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(command);
      setCopied(true);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), 2000);
    } catch {
      // Clipboard rejects in non-secure contexts / sandboxed iframes — degrade
      // quietly rather than flip to "Copied" and mislead into a paste that never happened.
    }
  };
  return (
    <div className="flex items-center gap-2 rounded-lg border border-border bg-foreground/[0.02] px-2.5 py-1.5">
      <code className="mono min-w-0 flex-1 truncate text-[11px] text-foreground/80">{command}</code>
      <button
        type="button"
        onClick={copy}
        aria-label={label}
        className="inline-flex shrink-0 items-center gap-1 rounded-md px-1.5 py-1 text-[11px] font-medium text-muted-foreground transition-[transform,background-color,color] duration-150 hover:bg-foreground/[0.04] hover:text-foreground active:scale-[0.96]"
      >
        {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
        {copied ? 'Copied' : 'Copy'}
      </button>
    </div>
  );
}

/**
 * The merge island's staged landing control (worktree-landing-strip
 * island-landing-states t4 happy path): a dumb, prop-driven walk from probe copy →
 * Prepare to land → preparing (stream one click away) → ready to land · verified →
 * Land (ff), plus the main-moved re-prepare. It renders whatever `landingState`
 * the server derives — never a client-trusted pill — and re-derives on every
 * refetch. Plane nomenclature is deliberate: PlaneTakeoff = prepare (clear the
 * runway), PlaneLanding = land (touchdown on main). The conflicts / failed rungs
 * and the full restore surface are t3.
 */
export function StagedLandingControl({
  landingState,
  busy = false,
  onPrepare,
  onLand,
  onRaise,
  onRestore,
  onOpenStream,
  landLog,
  runOutput,
  branch,
}: StagedLandingControlProps) {
  const { phase, probeClass, tipShape, reconcileRunId, canRestore, conflictedFiles } = landingState;

  return (
    <section aria-label="Land this work" className="flex flex-col gap-3">
      {phase === 'prepare' && (
        <div className="flex flex-col gap-3">
          <div>
            <StatusPill varName={probeTone(probeClass)} icon={<PlaneTakeoff className="h-3.5 w-3.5" />}>
              {probeCopy(probeClass)}
            </StatusPill>
          </div>
          <ActionButton
            onClick={onPrepare}
            disabled={busy}
            icon={<PlaneTakeoff className="h-4 w-4" />}
            label="Prepare to land"
            detail="Reconcile onto main — rebase, replay recorded resolutions, then verify build + tests."
          />
          {/* Secondary terminals — a merge-commit land or a raised PR. These BYPASS
              the reconcile + verify rung, so they land / hand off an unverified tip;
              the copy says so plainly. Offered only when the container wires them
              (onRaise present). The verified cross-strategy flow is a follow-on PRD. */}
          {onRaise && (
            <div className="mt-1 flex flex-col gap-2 border-t border-border pt-3">
              <p className="pretty text-[11px] leading-snug text-muted-foreground">
                Or land another way, <span className="font-medium text-foreground/80">without the verify rung</span>:
              </p>
              <div className="flex gap-2">
                <SecondaryTerminal icon={<GitMerge className="h-3.5 w-3.5" />} label="Merge commit" onClick={() => onLand('merge')} disabled={busy} />
                <SecondaryTerminal icon={<GitPullRequest className="h-3.5 w-3.5" />} label="Raise PR" onClick={onRaise} disabled={busy} />
              </div>
            </div>
          )}
        </div>
      )}

      {phase === 'preparing' && (
        <div
          className="flex flex-col gap-2 rounded-xl border p-3"
          style={{
            borderColor: 'color-mix(in oklab, var(--color-blue) 30%, transparent)',
            background: 'color-mix(in oklab, var(--color-blue) 6%, transparent)',
          }}
        >
          <div className="flex items-center justify-between gap-2">
            <StatusPill varName="--color-blue" icon={<Loader2 className="h-3.5 w-3.5 animate-spin" />} pulse>
              Preparing…
            </StatusPill>
            {onOpenStream && reconcileRunId && (
              <button
                type="button"
                onClick={() => onOpenStream(reconcileRunId)}
                className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-medium text-blue-500 transition-colors hover:bg-blue-500/10 active:scale-[0.96]"
              >
                <Radio className="h-3.5 w-3.5" />
                View stream
              </button>
            )}
          </div>
          <p className="pretty text-xs leading-snug text-muted-foreground">
            Reconciling onto main. The live run is one click away.
          </p>
          {landLog && landLog.length > 0 && (
            <div role="log" aria-live="polite" className="mono max-h-32 overflow-y-auto text-[11px] leading-relaxed text-muted-foreground">
              {landLog.map((line, i) => (
                <div key={i}>{line}</div>
              ))}
            </div>
          )}
          {/* The live command output beneath the phase labels — what turbo/vitest is
              actually printing, so a slow or wedged verify shows real progress. */}
          {runOutput && <RunOutputLog output={runOutput} tone="--color-blue" />}
        </div>
      )}

      {phase === 'ready-to-land' && (() => {
        const copy = landCopy(tipShape);
        return (
          <div className="flex flex-col gap-3">
            <div>
              <StatusPill varName="--color-done" icon={<CircleCheck className="h-3.5 w-3.5" />}>
                ready to land · verified
              </StatusPill>
            </div>
            {/* No aria-label override — the button's accessible name IS its honest
                label, so a merge-node tip reads "carries a merge commit" to SR users. */}
            <ActionButton
              onClick={() => onLand('ff-only')}
              disabled={busy}
              tone="--color-done"
              icon={<PlaneLanding className="h-4 w-4" />}
              label={copy.label}
              detail={copy.detail}
            />
            {copy.mergeNode && (
              <ActionButton
                onClick={onPrepare}
                disabled={busy}
                variant="ghost"
                icon={<PlaneTakeoff className="h-4 w-4 text-muted-foreground" />}
                label="Rebase to linear"
                detail="Prepare again to drop the merge node and land a linear tip."
              />
            )}
          </div>
        );
      })()}

      {phase === 'main-moved' && (
        <div className="flex flex-col gap-3">
          <div>
            <StatusPill varName="--color-warn" icon={<TriangleAlert className="h-3.5 w-3.5" />}>
              main moved · re-prepare needed
            </StatusPill>
          </div>
          <p className="pretty text-xs leading-snug text-muted-foreground">
            Main advanced under the verified tip — a fast-forward land would no longer apply cleanly. Prepare again to reconcile onto the new main.
          </p>
          <ActionButton
            onClick={onPrepare}
            disabled={busy}
            tone="--color-warn"
            icon={<PlaneTakeoff className="h-4 w-4" />}
            label="Prepare again"
            detail="Re-run the reconcile ladder onto the current main."
          />
        </div>
      )}

      {/* conflicts (t3) — the residual files the deterministic ladder + agent could
          not resolve, and the /merge human-rung hand-off (keyed by branch; the skill
          opens the worktree and reproduces the rebase). Restore is offered by the
          shared affordance below (the ladder left a pre-reconcile backup). */}
      {phase === 'conflicts' && (
        <div className="flex flex-col gap-3">
          <div>
            <StatusPill varName="--color-warn" icon={<TriangleAlert className="h-3.5 w-3.5" />}>
              {conflictCountLabel(conflictedFiles?.length)}
            </StatusPill>
          </div>
          {conflictedFiles && conflictedFiles.length > 0 && (
            <ul aria-label="Conflicted files" className="flex flex-col gap-1 rounded-xl border border-border p-2">
              {conflictedFiles.map((file) => (
                <li key={file} className="mono flex items-center gap-2 px-1 text-[11px] text-muted-foreground">
                  <FileWarning className="h-3.5 w-3.5 shrink-0" style={{ color: 'var(--color-warn)' }} />
                  <span className="truncate">{file}</span>
                </li>
              ))}
            </ul>
          )}
          {/* Only promise the /merge hand-off when the branch is known to key it —
              a branch-less state must not advertise an affordance that isn't rendered. */}
          {branch ? (
            <>
              <p className="pretty text-xs leading-snug text-muted-foreground">
                The deterministic ladder (rerere + recipes) and the headless agent couldn't resolve these. Resolve them by hand with the{' '}
                <span className="font-medium text-foreground/80">/merge</span> hand-off — it opens the branch's worktree, reproduces the rebase, and walks you to a verified, ready-to-land branch.
              </p>
              <CopyCommand command={`/merge ${branch}`} label="Copy /merge command" />
            </>
          ) : (
            <p className="pretty text-xs leading-snug text-muted-foreground">
              The deterministic ladder (rerere + recipes) and the headless agent couldn't resolve these. Resolve them by hand in the branch's worktree, then prepare again.
            </p>
          )}
        </div>
      )}

      {/* failed (t3) — never a bare "failed" word: name the rung, offer the run to
          inspect the failing step, and a Prepare again to retry the ladder. */}
      {phase === 'failed' && (
        <div className="flex flex-col gap-3">
          <div>
            <StatusPill varName="--color-phase-red" icon={<TriangleAlert className="h-3.5 w-3.5" />}>
              reconcile failed
            </StatusPill>
          </div>
          <p className="pretty text-xs leading-snug text-muted-foreground">
            The reconcile run did not complete — the failing step is below. Fix it, then prepare again.
          </p>
          {/* The failing step, inline: the tail of the run output carries the actual
              error (a red test, a broken build, `spawn turbo ENOENT`), so the failure
              is never a blank "reconcile failed" the user can't act on. */}
          {runOutput && <RunOutputLog output={runOutput} tone="--color-phase-red" />}
          <div className="flex gap-2">
            {onOpenStream && reconcileRunId && (
              <SecondaryTerminal icon={<Radio className="h-3.5 w-3.5" />} label="View run" onClick={() => onOpenStream(reconcileRunId)} />
            )}
            <SecondaryTerminal icon={<PlaneTakeoff className="h-3.5 w-3.5" />} label="Prepare again" onClick={onPrepare} disabled={busy} />
          </div>
        </div>
      )}

      {canRestore && onRestore && (
        <button
          type="button"
          onClick={onRestore}
          disabled={busy}
          className="inline-flex items-center gap-1.5 self-start rounded-lg px-2 py-1 text-xs font-medium text-muted-foreground transition-colors hover:text-foreground hover:bg-foreground/[0.04] active:scale-[0.96] disabled:opacity-60 disabled:active:scale-100"
        >
          <RotateCcw className="h-3.5 w-3.5" />
          Restore pre-rebase
        </button>
      )}
    </section>
  );
}

export default StagedLandingControl;
