import { useSearchParams } from 'react-router-dom';
import MiniStatusRail from './MiniStatusRail';
import { dedupeByBranch, type WorktreeBranchRef } from './worktree-branches';

/**
 * The PRD header's worktree affordance (worktree-teardown-surface task 8). It is
 * a TRIGGER only: clicking opens a full, content-replacing island by setting an
 * `?island=` param RepoDetailPage early-returns on.
 *
 * Two destinations, by how the PRD was delivered:
 *
 * - SEVERAL branches (a worker-delivered PRD — many features, each on its own
 *   run-branch) → the AGGREGATE teardown island (`?island=prd:<id>`), which
 *   lists every run-branch with its own land / remediate actions.
 * - a SINGLE worktree-backed branch → that branch's own merge island
 *   (`?island=<branch>`), the per-worktree surface the Worktrees tab renders
 *   (delivered features/tasks + a land action). `WorktreeMergeDetail` handles
 *   both an interactive worktree AND a lone worker run (it gates Reject on the
 *   row's own `isWorkerRun`), so this is right whether or not a run backs it.
 *
 * This is what lets an INTERACTIVELY-delivered PRD (one worktree, no runs) show
 * its real merge status instead of the teardown's "No worker runs on this PRD
 * yet." (fix: prd-merge-status-interactive-worktrees).
 *
 * The single-branch route is gated on `hasWorktree`: `?island=<branch>` is
 * resolved by RepoDetailPage against the deliverable-worktree queue, so a ref
 * that is NOT a live worktree would dead-end there — such a branch falls back
 * to the teardown aggregate instead.
 */
export interface PrdWorktreeDeliveryProps {
  /** The PRD id — the teardown island is keyed by it. */
  prdId: string;
  /** Worktree branches across the PRD's tasks; the indicator shows when non-empty. */
  branches: readonly WorktreeBranchRef[];
}

export function PrdWorktreeDelivery({ prdId, branches }: PrdWorktreeDeliveryProps) {
  const model = dedupeByBranch(branches);
  const [, setSearchParams] = useSearchParams();

  if (model.length === 0) return null;

  // One worktree-backed delivering branch ⇒ open that branch's worktree merge
  // island; several branches — or a lone ref with no live worktree — ⇒ the PRD
  // teardown aggregate keyed by prd id. The `hasWorktree` gate matters because
  // `?island=<branch>` is resolved against the deliverable-worktree queue, so a
  // branch with no worktree would dead-end there.
  const single = model.length === 1 && model[0].hasWorktree ? model[0] : null;
  const islandKey = single ? single.branch : `prd:${prdId}`;
  const openMergeSurface = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('island', islandKey);
      return next;
    });

  // The expanded (merge-mode) rail — its "View merge status" chip is the delivery
  // affordance; a PRD aggregates many tasks so it reads as interactive work here.
  return (
    <MiniStatusRail
      worktreeMode="merge"
      branches={branches}
      onMerge={openMergeSurface}
      isWorkerRun={false}
      where="local"
    />
  );
}

export default PrdWorktreeDelivery;
