import React from 'react';
import { ScrollText } from 'lucide-react';
import DecisionsList from './DecisionsList';
import AdrDetail from './AdrDetail';
import { ResizablePanelGroup, ResizablePanel, ResizableHandle } from './ui/resizable';
import { useAdrs } from '../hooks/useAdrs';
import { usePanelSizeMemory } from '../hooks/usePanelSizeMemory';

export interface DecisionsViewProps {
  repoId: string;
  /** Selected ADR slug from the URL (`?item=<slug>`), or null when none. */
  selectedSlug: string | null;
  onSelect: (slug: string) => void;
  /** Open the selected ADR's assets (the shared kind-`adr` AssetsIsland). */
  onOpenAssets: () => void;
}

/**
 * The Decisions surface (adr-browser / decisions-list-detail-ui). A list +
 * detail split like plans/fixes: a sidebar of ALL ADRs (Task 1) beside a detail
 * pane (Task 2 renders the selected ADR's markdown there). Replaces the
 * gallery-only render branch for the Decisions view. Honest loading / error
 * states around the list.
 */
const DecisionsView: React.FC<DecisionsViewProps> = ({ repoId, selectedSlug, onSelect, onOpenAssets }) => {
  const { adrs, loading, error } = useAdrs(repoId);
  const panels = usePanelSizeMemory('decisions');
  const selectedAdr = selectedSlug ? adrs.find((a) => a.slug === selectedSlug) ?? null : null;

  return (
    <ResizablePanelGroup direction="horizontal" className="h-full min-h-0 overflow-hidden" onLayout={panels.onLayout}>
      {/* Sidebar: all ADRs, behind a draggable splitter like the other
          list+detail surfaces (plans / worktrees). */}
      <ResizablePanel defaultSize={panels.defaultSize(0, 28)} minSize={18}>
        <div className="flex h-full min-h-0 flex-col overflow-y-auto">
          {loading ? (
            <div className="flex items-center justify-center p-8">
              <div className="h-8 w-8 animate-spin rounded-full border-b-2 border-primary" />
            </div>
          ) : error ? (
            <p role="alert" className="p-4 text-sm text-red-400">
              Couldn&rsquo;t load decisions — {error}
            </p>
          ) : (
            <DecisionsList adrs={adrs} selectedSlug={selectedSlug} onSelect={onSelect} />
          )}
        </div>
      </ResizablePanel>
      <ResizableHandle withHandle />
      {/* Detail pane: the selected ADR's markdown, or a prompt when none is
          chosen. Keyed by slug so switching selection remounts the fetch. */}
      <ResizablePanel defaultSize={panels.defaultSize(1, 72)}>
        <div className="flex h-full min-h-0 flex-col overflow-y-auto">
          {selectedSlug ? (
            <AdrDetail
              key={selectedSlug}
              repoId={repoId}
              slug={selectedSlug}
              hasAssets={selectedAdr?.hasAssets ?? false}
              assetCount={selectedAdr?.assetCount ?? 0}
              onOpenAssets={onOpenAssets}
            />
          ) : (
            <div className="grid flex-1 place-items-center p-8 text-center">
              <div className="flex flex-col items-center gap-2 text-muted-foreground">
                <ScrollText className="h-8 w-8" aria-hidden="true" />
                <p className="text-sm">Select a decision to view it</p>
              </div>
            </div>
          )}
        </div>
      </ResizablePanel>
    </ResizablePanelGroup>
  );
};

export default DecisionsView;
