import type { AssetItemKind } from '@/services/api';

/**
 * The design-assets view (surface-design-assets F4) is a MODE of the
 * currently-open item, not a standalone view: the URL already identifies the
 * item via `?view=<area>&item=<slug>`, so `?assets` is a bare marker and the
 * item's kind is derived from the active work area. Returns null for areas that
 * carry no assets (spikes / quality / worktrees), so a stray marker there falls
 * through to the normal workspace.
 */
export function deriveAssetsKind(activeArea: string): AssetItemKind | null {
  if (activeArea === 'plans') return 'prd';
  if (activeArea === 'fixes') return 'fix';
  // Decisions is its own non-work-area view; unlike plans/fixes the selected
  // item is an ADR slug (the ADR detail's Assets affordance sets ?assets).
  if (activeArea === 'decisions') return 'adr';
  return null;
}
