import React, { createContext, useContext, useState, useEffect } from 'react';
import { getStoredCredentials, authenticateLibrary } from '../services/api';

type ConnectionStatus = 'idle' | 'connected' | 'error' | 'checking';

interface LibraryContextType {
  connectionStatus: ConnectionStatus;
  authToken: string | null;
  /** Whether a tiny-brain API client id + secret are configured. */
  hasCredentials: boolean;
  checkConnection: () => Promise<void>;
  getAuthHeaders: () => Record<string, string> | null;
}

const LibraryContext = createContext<LibraryContextType>({
  connectionStatus: 'idle',
  authToken: null,
  hasCredentials: false,
  checkConnection: async () => {},
  getAuthHeaders: () => null
});

export const useLibrary = () => useContext(LibraryContext);

export const LibraryProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('checking');
  const [authToken, setAuthToken] = useState<string | null>(null);
  const [hasCredentials, setHasCredentials] = useState(false);

  const checkConnection = async () => {
    setConnectionStatus('checking');

    try {
      // First check for stored credentials — auth is only attempted when a
      // client id + secret are present.
      const creds = await getStoredCredentials();
      const haveCreds = !!(creds.clientId && creds.clientSecret);
      setHasCredentials(haveCreds);
      if (!haveCreds) {
        setConnectionStatus('idle');
        setAuthToken(null);
        return;
      }

      // For authentication, we need to pass empty strings to trigger
      // the server to use stored credentials
      const authResult = await authenticateLibrary('', '');

      if (authResult.success && authResult.token) {
        setAuthToken(authResult.token);
        setConnectionStatus('connected');
      } else {
        setAuthToken(null);
        setConnectionStatus('error');
      }
    } catch (err) {
      console.error('Failed to check library connection:', err);
      setAuthToken(null);
      setConnectionStatus('error');
    }
  };

  const getAuthHeaders = () => {
    if (!authToken) return null;
    return {
      'Authorization': `Bearer ${authToken}`
    };
  };

  // Check connection on mount
  useEffect(() => {
    checkConnection();
  }, []);

  return (
    <LibraryContext.Provider value={{ connectionStatus, authToken, hasCredentials, checkConnection, getAuthHeaders }}>
      {children}
    </LibraryContext.Provider>
  );
};