import React from 'react';
import { cn } from '@/lib/utils';
import { Package, Puzzle, Bot, Webhook, Server } from 'lucide-react';
import { SelectableCard } from './ui/selectable-card';
import { Badge } from './ui/badge';

export interface RepoPlugin {
  name: string;
  version: string;
  description: string;
  scope: 'user' | 'project' | 'local';
  path: string;
  repoPath?: string;
  manifest: {
    name: string;
    version?: string;
    description?: string;
    author?: {
      name?: string;
      email?: string;
      url?: string;
    };
    keywords?: string[];
  };
  components: {
    skills: string[];
    agents: string[];
    hasHooks: boolean;
    hasMcp: boolean;
  };
}

interface RepoPluginListProps {
  plugins: RepoPlugin[];
  selectedPluginId: string | null;
  onSelectPlugin: (pluginId: string) => void;
}

interface PluginCardProps {
  plugin: RepoPlugin;
  isSelected: boolean;
  onClick: () => void;
}

const scopeColors: Record<string, string> = {
  user: 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-300',
  project: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300',
  local: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300',
};

const scopeLabels: Record<string, string> = {
  user: 'User',
  project: 'Project',
  local: 'Local',
};

const PluginCard: React.FC<PluginCardProps> = ({ plugin, isSelected, onClick }) => {
  const { components } = plugin;

  return (
    <SelectableCard isSelected={isSelected} onClick={onClick}>
      <div className="flex items-start gap-3">
        <div className={cn(
          'p-2 rounded-lg',
          isSelected ? 'bg-primary/10' : 'bg-muted'
        )}>
          <Package className="h-4 w-4 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h3 className="font-medium text-sm truncate">{plugin.name}</h3>
            <Badge variant="outline" className="text-xs">{plugin.version}</Badge>
          </div>
          {plugin.description && (
            <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">
              {plugin.description}
            </p>
          )}
          <div className="flex items-center gap-2 mt-2">
            <Badge className={cn('text-xs', scopeColors[plugin.scope])}>
              {scopeLabels[plugin.scope]}
            </Badge>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              {components.skills.length > 0 && (
                <span className="flex items-center gap-0.5">
                  <Puzzle className="h-3 w-3" />
                  {components.skills.length}
                </span>
              )}
              {components.agents.length > 0 && (
                <span className="flex items-center gap-0.5">
                  <Bot className="h-3 w-3" />
                  {components.agents.length}
                </span>
              )}
              {components.hasHooks && (
                <Webhook className="h-3 w-3" />
              )}
              {components.hasMcp && (
                <Server className="h-3 w-3" />
              )}
            </div>
          </div>
        </div>
      </div>
    </SelectableCard>
  );
};

const RepoPluginList: React.FC<RepoPluginListProps> = ({
  plugins,
  selectedPluginId,
  onSelectPlugin,
}) => {
  if (plugins.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <div className="text-6xl mb-4">
          <Package className="h-16 w-16 text-muted-foreground/30" />
        </div>
        <p className="text-muted-foreground text-center">No plugins available</p>
        <p className="text-muted-foreground/70 text-sm text-center mt-2">
          Install plugins to <code className="px-1 bg-muted rounded">~/.claude/plugins/</code> or <code className="px-1 bg-muted rounded">.claude/plugins/</code>
        </p>
      </div>
    );
  }

  return (
    <div className="p-3 space-y-2" role="list" aria-label="Available plugins">
      {plugins.map((plugin) => (
        <PluginCard
          key={plugin.path}
          plugin={plugin}
          isSelected={plugin.path === selectedPluginId}
          onClick={() => onSelectPlugin(plugin.path)}
        />
      ))}
    </div>
  );
};

export default RepoPluginList;
