/**
 * SSE Parser - Parse Server-Sent Events from fetch response
 */

export interface SSEEvent {
  event: string;
  data: unknown;
  /** The SSE `id:` field, when present — the canonical reconnect/dedup key. */
  id?: string;
}

/**
 * Parse SSE events from a complete text block
 * Events are separated by double newlines
 * Only complete events (followed by \n\n) are parsed
 */
export function parseSSEEvents(text: string): SSEEvent[] {
  if (!text) {
    return [];
  }

  // Check if text ends with double newline - if not, there's incomplete data
  const endsComplete = text.endsWith('\n\n');

  const events: SSEEvent[] = [];

  // Split by double newline to get individual events
  const eventBlocks = text.split('\n\n');

  // If text doesn't end with \n\n, the last block is incomplete
  const blocksToProcess = endsComplete ? eventBlocks : eventBlocks.slice(0, -1);

  for (const block of blocksToProcess) {
    if (!block.trim()) {
      continue;
    }

    let eventType = 'message';
    let data: string | undefined;
    let id: string | undefined;

    const lines = block.split('\n');
    for (const line of lines) {
      // Skip comments
      if (line.startsWith(':')) {
        continue;
      }

      if (line.startsWith('event:')) {
        eventType = line.slice(6).trim();
      } else if (line.startsWith('data:')) {
        data = line.slice(5).trim();
      } else if (line.startsWith('id:')) {
        id = line.slice(3).trim();
      }
    }

    // Parse JSON data if possible
    let parsedData: unknown = data;
    if (data) {
      try {
        parsedData = JSON.parse(data);
      } catch {
        // Keep as string if not valid JSON
        parsedData = data;
      }
    }

    events.push({
      event: eventType,
      data: parsedData,
      // An empty `id:` line carries no id — normalize to undefined so the
      // field is symmetric with frameSSE, which omits the line when empty.
      id: id || undefined,
    });
  }

  return events;
}

/**
 * Parse SSE events from a streaming buffer
 * Returns parsed events and the remaining buffer
 */
export function parseSSEStream(buffer: string): { events: SSEEvent[]; buffer: string } {
  const events: SSEEvent[] = [];
  let remaining = buffer;

  // Look for complete events (ending with \n\n)
  let lastDoubleNewline = remaining.lastIndexOf('\n\n');

  while (lastDoubleNewline !== -1) {
    // Find the start of this event sequence
    const completeText = remaining.slice(0, lastDoubleNewline + 2);
    remaining = remaining.slice(lastDoubleNewline + 2);

    // Parse the complete events
    const parsed = parseSSEEvents(completeText);
    events.push(...parsed);

    // Check for more complete events in remaining
    lastDoubleNewline = remaining.lastIndexOf('\n\n');
  }

  return { events, buffer: remaining };
}
