/**
 * SSE-driven refetch trigger for the spike detail pane.
 *
 * PRD `progress-json-as-event-projection` Feature 4 / Task 5 — the
 * dashboard spike detail now reads tasks from markdown via the
 * projector (Task 3), so when `docs/spikes/<id>.md` changes on disk
 * the server emits a `spike-doc-change` SSE event. This hook listens
 * to that channel scoped to `(repoId, spikeId)` and invokes the
 * supplied `onChange` callback so the parent can refetch the
 * detail.
 *
 * Spike events themselves are intentionally dropped today (no
 * `TaskRef.kind === 'spike'` variant — see `projectSpikeEntry`'s
 * comment), so this doc-level signal is the only live overlay
 * surface the spike detail needs.
 */

import { useEffect } from 'react';
import { sseManager, type SSEEvent } from '../services/SSEManager';

export function useSpikeDocLive(
  repoId: string | null,
  spikeId: string | null,
  onChange: () => void,
  enabled = true,
): void {
  useEffect(() => {
    if (!enabled || !repoId || !spikeId) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'spikeDocChange') return;
      if (event.repoId !== repoId) return;
      if (event.spikeId !== spikeId) return;
      onChange();
    };

    return sseManager.on('spikeDocChange', handle);
  }, [repoId, spikeId, enabled, onChange]);
}
