import React from 'react';
import { Routes, Route } from 'react-router-dom';
import TBSPersonasPage from './pages/TBSPersonasPage';
import PersonaDetailPage from './pages/PersonaDetailPage';
import ReposPage from './pages/ReposPage';
import RepoDetailPage from './pages/RepoDetailPage';
import SettingsPane from './components/SettingsPane';
import EnvironmentsPage from './pages/EnvironmentsPage';
import WorkersPage from './pages/WorkersPage';

export interface AppRoutesProps {
  /**
   * What the bare-root (`/`) and catch-all (`*`) routes render. `null` while the
   * persona count is still loading (so we don't redirect prematurely); otherwise
   * a `<Navigate>` to the default landing.
   */
  landing: React.ReactNode;
}

/**
 * The app's route table, extracted from App so the route ↔ page wiring — in
 * particular the Execution coming-soon surfaces — is renderable in a test
 * without standing up the whole shell.
 */
export const AppRoutes: React.FC<AppRoutesProps> = ({ landing }) => {
  return (
    <Routes>
      <Route path="/" element={landing} />
      <Route path="/personas" element={<TBSPersonasPage />} />
      <Route path="/personas/:personaId" element={<PersonaDetailPage />} />
      <Route path="/repos" element={<ReposPage />} />
      <Route path="/repos/:repoId" element={<RepoDetailPage />} />
      <Route path="/environments" element={<EnvironmentsPage />} />
      <Route path="/workers" element={<WorkersPage />} />
      <Route path="/settings" element={<SettingsPane />} />
      {/* Unknown paths (e.g. a stale /plugins deep-link after the section was
          removed) redirect to the default rather than rendering a blank pane. */}
      <Route path="*" element={landing} />
    </Routes>
  );
};

export default AppRoutes;
