import { useEffect, useState } from 'react';
import type { RunEvent } from '@magic-ingredients/tiny-brain-core';
import { parseSSEStream } from '../utils/sse-parser';

export interface UseRunStreamResult {
  /** Events received so far, in arrival order, deduped by the SSE frame id. */
  events: RunEvent[];
  /** True while a stream is open. */
  connected: boolean;
  /** Last non-abort failure, or null. Lets the caller distinguish a clean
   * end (run exited) from a failed/dropped one. */
  error: string | null;
}

export interface UseRunStreamOptions {
  /** Delay before reconnecting after an unexpected drop (ms). Default 1000. */
  reconnectDelayMs?: number;
}

const DEFAULT_RECONNECT_DELAY_MS = 1000;

/** A frame's `data` is a usable RunEvent only when it parsed to an object with
 * a string `type` — guards against `data: null` / non-JSON `data:` lines that
 * `parseSSEStream` surfaces as `null` / a raw string. */
function isRunEvent(data: unknown): data is RunEvent {
  return typeof data === 'object' && data !== null && typeof (data as { type?: unknown }).type === 'string';
}

/**
 * Subscribe to a run's activity stream (ADR-0017). Opens a fetch stream to the
 * per-run SSE bridge route, parses each frame with the shared SSE decode
 * primitive, and dedups by the SSE `id` that primitive surfaces (the route's
 * stamped `RunEvent.id`, emitted as the SSE id line). On an unexpected drop (the
 * stream ends before the run's `exit` event and the effect is still live) it
 * reconnects; the server replays history and the shared `seen` Set dedups it,
 * so reconnection renders no duplicates. Activity only — the `exit` event is
 * surfaced as data (a liveness/fetch trigger for the caller), never a status.
 */
export function useRunStream(
  repoId: string,
  runId: string,
  options: UseRunStreamOptions = {},
): UseRunStreamResult {
  const reconnectDelayMs = options.reconnectDelayMs ?? DEFAULT_RECONNECT_DELAY_MS;
  const [events, setEvents] = useState<RunEvent[]>([]);
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setEvents([]);
    setConnected(false);
    setError(null);

    // No run to subscribe to yet (e.g. a skill run before its runId is known).
    // Stay idle rather than fetching a bogus `/runs//stream` URL.
    if (!repoId || !runId) return;

    const controller = new AbortController();
    // Guards every state update so a torn-down effect (unmount / runId change)
    // can't write state — closing the runId-change race where a stale run's
    // teardown would otherwise clobber the new run's `connected`.
    let active = true;
    const seen = new Set<string>();

    const url = `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}/stream`;

    void (async () => {
      while (active && !controller.signal.aborted) {
        let sawExit = false;
        try {
          const response = await fetch(url, { signal: controller.signal });
          if (!response.ok || !response.body) {
            if (active) setError(`run stream request failed (${response.status})`);
            break;
          }
          if (active) {
            setConnected(true);
            setError(null);
          }

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = '';
          // eslint-disable-next-line no-constant-condition
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            buffer += decoder.decode(value, { stream: true });
            const { events: frames, buffer: remaining } = parseSSEStream(buffer);
            buffer = remaining;

            const fresh: RunEvent[] = [];
            for (const frame of frames) {
              if (!isRunEvent(frame.data)) continue;
              const event = frame.data;
              // Dedup by the SSE `id:` the decode primitive surfaces — the
              // canonical reconnect key the route emits — not the envelope.
              if (frame.id !== undefined) {
                if (seen.has(frame.id)) continue;
                seen.add(frame.id);
              }
              if (event.type === 'exit') sawExit = true;
              fresh.push(event);
            }
            if (fresh.length > 0 && active) setEvents((prev) => [...prev, ...fresh]);
          }
        } catch (err) {
          // Abort on unmount/runId change is expected — stop, don't reconnect.
          if (err instanceof Error && err.name === 'AbortError') return;
          if (active) setError(err instanceof Error ? err.message : 'run stream error');
        } finally {
          if (active) setConnected(false);
        }

        // Clean end (run exited) or torn down → stop. Otherwise the connection
        // dropped mid-run: wait, then reconnect (history replays, `seen` dedups).
        if (sawExit || !active || controller.signal.aborted) break;
        await new Promise((resolve) => setTimeout(resolve, reconnectDelayMs));
      }
    })();

    return () => {
      active = false;
      controller.abort();
    };
  }, [repoId, runId, reconnectDelayMs]);

  return { events, connected, error };
}
