import { cn } from '@/lib/utils';

export interface GradientProgressProps {
  /** Completion percentage; clamped to the 0–100 range. */
  value: number;
  /** Extra classes for the track (e.g. `mt-3`, `flex-1`). */
  className?: string;
}

/**
 * The gradient progress bar from the UI Refresh design system: a recessed track
 * with a pink→blue gradient fill. Exposes the standard `progressbar` ARIA role
 * so the completion value is conveyed to assistive tech.
 */
export function GradientProgress({ value, className }: GradientProgressProps) {
  // Guard non-finite input (e.g. a `done / total` division with total 0) so we
  // never emit `aria-valuenow="NaN"` / `width: NaN%`.
  const safe = Number.isFinite(value) ? value : 0;
  const pct = Math.min(100, Math.max(0, safe));
  return (
    <div
      role="progressbar"
      aria-valuenow={Math.round(pct)}
      aria-valuemin={0}
      aria-valuemax={100}
      className={cn('progress-track h-1.5 w-full overflow-hidden rounded-full', className)}
    >
      <div
        data-testid="gradient-progress-fill"
        className="h-full rounded-full bg-gradient-to-r from-pink to-blue"
        style={{ width: `${pct}%` }}
      />
    </div>
  );
}

export default GradientProgress;
