import React from 'react';
import { KeyRound } from 'lucide-react';

/**
 * Minimal inline marks for credential providers (fix:
 * env-edit-keys-and-table-nits task 9). Self-drawn approximations — no
 * external assets can be fetched (CSP/self-contained bundle), so these are
 * recognisable-at-12px monograms, not the official artwork. Unknown
 * providers fall back to the key glyph.
 */
export const ProviderGlyph: React.FC<{ provider: string; className?: string }> = ({
  provider,
  className = 'h-3 w-3',
}) => {
  if (provider === 'anthropic') {
    return (
      <svg
        data-testid="provider-glyph-anthropic"
        viewBox="0 0 24 24"
        fill="currentColor"
        className={className}
        aria-hidden="true"
      >
        <path d="M13.83 3.5h-3.66L3.4 20.5h3.72l1.34-3.56h7.08l1.34 3.56h3.72L13.83 3.5Zm-4.2 10.32L12 7.06l2.37 6.76H9.63Z" />
      </svg>
    );
  }
  if (provider === 'openai') {
    return (
      <svg
        data-testid="provider-glyph-openai"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        className={className}
        aria-hidden="true"
      >
        <path d="M12 3l7.8 4.5v9L12 21l-7.8-4.5v-9L12 3Z" />
        <path d="M12 7.2l4.16 2.4v4.8L12 16.8l-4.16-2.4V9.6L12 7.2Z" />
      </svg>
    );
  }
  return <KeyRound data-testid={`provider-glyph-${provider}`} className={className} aria-hidden="true" />;
};
