import React from 'react';
import { Archive, Images } from 'lucide-react';
import { cn } from '@/lib/utils';
import CopyIdButton from './CopyIdButton';
import { DetailHeader } from './DetailHeader';
import MiniStatusRail from './MiniStatusRail';
import PrdWorktreeDelivery from './PrdWorktreeDelivery';
import { type WorktreeBranchRef } from './worktree-branches';
import { deriveWorktreeBranches } from '../utils/effective-task-status';
import type { Plan } from '../types';

type PlanStatus = Plan['status'];

interface PlanDetailHeaderProps {
  /** Plan title, rendered as the heading. */
  title: string;
  /** PRD id/slug; a copy affordance is shown next to the title when set. */
  prdId?: string;
  /** Lifecycle status, stated by the eyebrow (no separate pill). */
  status?: PlanStatus;
  /** Number of features in the plan. */
  featureCount: number;
  /** ISO timestamp of the last update; formatted as e.g. "29 May 2026". */
  lastUpdated?: string;
  /** Whether the plan is archived — flips the action between Archive/Unarchive. */
  isArchived?: boolean;
  /** Archive/unarchive handlers. The action button only renders when the
   *  relevant handler is wired, so unwired contexts (stories, read-only shells)
   *  show no dead button rather than a silent no-op. */
  onArchive?: () => void;
  onUnarchive?: () => void;
  /** Worktree branches in use across all of this PRD's tasks; surfaced as a
   *  compact tag in the header. Empty/absent ⇒ no tag. */
  worktrees?: readonly WorktreeBranchRef[];
  /** The repo this PRD belongs to. When present the worktree indicator becomes
   *  the affordance that opens the branch-keyed delivery island; absent (legacy
   *  read-only shells) ⇒ a glance-only tag. */
  repoId?: string;
  /** Whether the PRD carries design assets (surface-design-assets F3). */
  hasAssets?: boolean;
  /** Opens the assets view. The Assets action renders only when both this is
   *  wired and `hasAssets` is set — no dead button in read-only shells. */
  onOpenAssets?: () => void;
}

/** Derive the header's display props from a Plan, so every render site (the PRD
 *  view and the legacy dashboard fallback) maps the plan the same way. */
export function planHeaderPropsFromPlan(
  plan: Plan,
): Omit<PlanDetailHeaderProps, 'onArchive' | 'onUnarchive'> {
  return {
    title: plan.title || plan.name || '',
    prdId: plan.prdId || plan.id,
    status: plan.status,
    featureCount: plan.features?.length ?? plan.metadata?.totalFeatures ?? plan.featureCount ?? 0,
    lastUpdated: plan.lastUpdated || plan.updatedAt,
    isArchived: plan.type === 'archived',
    worktrees: deriveWorktreeBranches((plan.features ?? []).flatMap((f) => f.tasks ?? []), plan.sourceWorktree),
    hasAssets: plan.hasAssets,
  };
}

const STATUS_LABELS: Record<PlanStatus, string> = {
  not_started: 'Not Started',
  in_progress: 'In Progress',
  completed: 'Completed',
};

// Eyebrow accent per status — the eyebrow alone states the status, matching the
// mockup (no separate status pill in the plan detail header).
const STATUS_TONE: Record<PlanStatus, string> = {
  not_started: 'text-muted-foreground',
  in_progress: 'text-blue',
  completed: 'text-done',
};

function formatUpdated(iso: string | undefined): string {
  if (!iso) return 'Unknown';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return 'Unknown';
  return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

/**
 * The plan detail header from the UI Refresh mockup: a status eyebrow, the plan
 * title with a copy-id affordance, and a "{n} features · last updated {date}"
 * line carrying the Archive/Unarchive action. The status is conveyed by the
 * eyebrow alone — there is no separate status pill here.
 */
const PlanDetailHeader: React.FC<PlanDetailHeaderProps> = ({
  title,
  prdId,
  status = 'not_started',
  featureCount,
  lastUpdated,
  isArchived = false,
  onArchive,
  onUnarchive,
  worktrees = [],
  repoId,
  hasAssets = false,
  onOpenAssets,
}) => {
  const statusLabel = STATUS_LABELS[status];
  const statusTone = STATUS_TONE[status];
  const archiveAction = isArchived ? onUnarchive : onArchive;

  // The PRD header's worktree affordance sits RHS in the eyebrow row. In a repo
  // scope it is the delivery affordance (opens the branch-keyed island, with a
  // chooser for multi-worktree PRDs); a read-only shell shows a glance-only
  // (no-onMerge) merge-mode rail. A PRD aggregates many tasks, so it reads as
  // interactive/local work here.
  const rail =
    worktrees.length > 0 ? (
      <div data-testid="prd-header-worktrees">
        {repoId && prdId ? (
          <PrdWorktreeDelivery prdId={prdId} branches={worktrees} />
        ) : (
          <MiniStatusRail worktreeMode="merge" branches={worktrees} isWorkerRun={false} where="local" />
        )}
      </div>
    ) : undefined;

  // Header action cluster: Assets · Archive. The Assets action opens the assets
  // view (surface-design-assets F3), rendered only when the PRD has assets and a
  // handler is wired — no dead button in read-only shells. Computed as a node so
  // an empty cluster stays `undefined` (DetailHeader then renders no aside).
  const actionClass =
    'inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground';
  const assetsButton =
    hasAssets && onOpenAssets ? (
      <button type="button" onClick={onOpenAssets} aria-label="View plan assets" className={actionClass}>
        <Images className="h-3.5 w-3.5" /> Assets
      </button>
    ) : null;
  const archiveButton = archiveAction ? (
    <button
      type="button"
      onClick={archiveAction}
      aria-label={isArchived ? 'Unarchive' : 'Archive'}
      className={actionClass}
    >
      <Archive className="h-3.5 w-3.5" />
      {isArchived ? 'Unarchive' : 'Archive'}
    </button>
  ) : null;
  const actions =
    assetsButton || archiveButton ? (
      <>
        {assetsButton}
        {archiveButton}
      </>
    ) : undefined;

  return (
    <DetailHeader
      testId="plan-detail-header"
      eyebrow={<p className={cn('eyebrow text-[10px]', statusTone)}>Plan · {statusLabel}</p>}
      rail={rail}
      title={<h1 className="display text-2xl font-bold leading-snug">{title}</h1>}
      titleAdornment={prdId ? <CopyIdButton value={prdId} kind="PRD" className="flex-shrink-0" /> : undefined}
      meta={
        <p className="text-sm text-muted-foreground">
          {featureCount} {featureCount === 1 ? 'feature' : 'features'} · last updated {formatUpdated(lastUpdated)}
        </p>
      }
      actions={actions}
    />
  );
};

export default PlanDetailHeader;
