import { useEffect, useState } from 'react';
import { fetchAdrs, type Adr } from '../services/api';

/**
 * The Decisions view's data feed (adr-browser / decisions-list-detail-ui):
 * every ADR in the repo (via `GET /adrs`), loaded on mount and whenever repoId
 * changes, with honest loading / error states. Read-only — the ADR corpus is
 * git-authored, so there is no create/mutate surface here.
 */
export function useAdrs(repoId: string | undefined) {
  const [adrs, setAdrs] = useState<Adr[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!repoId) {
      // No repo to read — settle to an empty, non-loading state rather than
      // spinning forever (the hook advertises `string | undefined`).
      setAdrs([]);
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchAdrs(repoId)
      .then((data) => {
        if (!cancelled) setAdrs(data);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : 'Failed to load decisions');
        setAdrs([]);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [repoId]);

  return { adrs, loading, error };
}
