import { Island } from './Island';
import { WorktreeMergeContent, type WorktreeMergeContentProps } from './WorktreeMergeContent';

// The merge surface content lives in WorktreeMergeContent (container-agnostic);
// this is the OVERLAY composition of it — the same content inside the shared
// Island shell. The inline two-pane detail pane renders WorktreeMergeContent
// directly. TeardownPartSelection is re-exported so existing importers
// (WorktreeDeliveryIsland) keep their `./WorktreeMergeIsland` import path.
export type { TeardownPartSelection } from './WorktreeMergeContent';

export interface WorktreeMergeIslandProps extends WorktreeMergeContentProps {
  open: boolean;
  onClose: () => void;
}

/**
 * The worktree-merge surface as a full-view overlay: the shared {@link Island}
 * shell wrapping {@link WorktreeMergeContent}. Opens over the repo view from a
 * fix/PRD worktree marker (`?island=<branch>`). Presentational + dumb — the
 * parent owns data, the POSTs and the marker wiring.
 */
export function WorktreeMergeIsland({ open, onClose, ...content }: WorktreeMergeIslandProps) {
  return (
    <Island open={open} onClose={onClose} ariaLabel="Worktree delivery">
      <WorktreeMergeContent onClose={onClose} {...content} />
    </Island>
  );
}

export default WorktreeMergeIsland;
