import { useSearchParams } from 'react-router-dom';
import { ScrollText, Settings } from 'lucide-react';
import { cn } from '@/lib/utils';
import { QualitySparkline, RAIL_CONTROL, RAIL_HOVER, RAIL_SELECTED } from './railControls';

/**
 * The repo workspace's Quality and Settings view-switches, surfaced in the top
 * breadcrumb rail. Both are URL-driven (`?view=quality` / `?settings`), the same
 * params RepoDetailPage reads and the breadcrumb crumbs already navigate to — so
 * these are permanent shortcuts to those nav actions, no prop threading from the
 * page below the global header.
 */
export function RepoViewControls({ className }: { className?: string }) {
  const [searchParams, setSearchParams] = useSearchParams();

  const settingsOpen =
    searchParams.get('settings') !== null || searchParams.get('section') !== null;
  const qualityActive = !settingsOpen && searchParams.get('view') === 'quality';
  const decisionsActive = !settingsOpen && searchParams.get('view') === 'decisions';

  // Mirror RepoDetailPage.setActiveTab('quality'): select Quality and drop any
  // open Settings + the previous area's item/analyser drill-downs.
  const openQuality = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('view', 'quality');
      next.delete('settings');
      next.delete('section');
      next.delete('item');
      next.delete('analyser');
      return next;
    });

  // Mirror setActiveTab('decisions'): select the ADR assets gallery and drop
  // the same drill-downs so a stale item/analyser can't leak into it.
  const openDecisions = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('view', 'decisions');
      next.delete('settings');
      next.delete('section');
      next.delete('item');
      next.delete('analyser');
      next.delete('assets');
      return next;
    });

  // Mirror RepoDetailPage.openSettings: Settings is an overlay view, so it only
  // sets `?settings` and leaves the underlying work area/view untouched.
  const openSettings = () =>
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('settings', '');
      return next;
    });

  return (
    <div className={cn('flex shrink-0 items-center gap-2', className)}>
      {/* Presentational scope label — these controls act on the current repo,
          not global state. Sits inside the group (adjacent to the controls), so
          it reads as scoping them rather than as a separate nav item. */}
      <span className="mono text-[11px] uppercase tracking-wider text-muted-foreground">Repo:</span>

      <button
        type="button"
        onClick={openQuality}
        aria-current={qualityActive ? 'page' : undefined}
        className={cn(RAIL_CONTROL, qualityActive ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <QualitySparkline />
        Quality
      </button>

      <button
        type="button"
        onClick={openDecisions}
        aria-current={decisionsActive ? 'page' : undefined}
        className={cn(RAIL_CONTROL, decisionsActive ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <ScrollText className="h-4 w-4" />
        Decisions
      </button>

      <span className="h-7 w-px self-center bg-border-strong" aria-hidden="true" />

      <button
        type="button"
        onClick={openSettings}
        aria-current={settingsOpen ? 'page' : undefined}
        className={cn(RAIL_CONTROL, settingsOpen ? RAIL_SELECTED : cn('text-muted-foreground', RAIL_HOVER))}
      >
        <Settings className="h-4 w-4" />
        Settings
      </button>
    </div>
  );
}

export default RepoViewControls;
