import type { StructuredRecommendation } from '../types';

/**
 * "Worth doing" ranks suggestions by risk reduced — the recommendation's
 * priority — and deliberately NOT by estimatedScoreGain (points gained). A
 * sharp critical risk outranks a high-points cosmetic win.
 */

const PRIORITY_LEVEL: Record<string, number> = {
  critical: 5,
  high: 4,
  medium: 3,
  low: 2,
};

/** Higher = more risk reduced. Numeric priority 1 is the most urgent. */
export function riskScore(rec: StructuredRecommendation): number {
  const priority = rec.priority;
  if (typeof priority === 'number') {
    return 6 - Math.min(5, Math.max(1, priority));
  }
  return PRIORITY_LEVEL[priority] ?? 1;
}

export function rankWorthDoing(
  recs: ReadonlyArray<StructuredRecommendation>,
): StructuredRecommendation[] {
  return recs
    .map((rec, index) => ({ rec, index }))
    // Stable: ties keep input order (index is the tiebreak).
    .sort((a, b) => riskScore(b.rec) - riskScore(a.rec) || a.index - b.index)
    .map(({ rec }) => rec);
}
