import { useCallback, useEffect, useState } from 'react';

/**
 * Client view of a worker as the global /api/workers routes return it —
 * the named (agent · model · effort · environment) profile work is
 * dispatched to.
 */
export interface WorkerView {
  name: string;
  adapter: string;
  environment: string;
  model: string;
  effort: 'low' | 'medium' | 'high';
  timeoutMs?: number;
}

/** One manual probe outcome, as POST /api/workers/:name/probe returns it. */
export interface WorkerProbeView {
  worker: string;
  ok: boolean;
  probedAt: string;
  reason?: string;
}

export type CreateWorkerInput = Omit<WorkerView, 'timeoutMs'>;

/** One provider's models as offered to an agent, as the server gates them. */
export interface AgentModelGroupView {
  provider: string;
  providerLabel: string;
  /** False = drivable but keyless in the environment — render locked. */
  enabled: boolean;
  models: string[];
}

export interface AgentOptionsView {
  agent: string;
  agentLabel: string;
  groups: AgentModelGroupView[];
}

/**
 * The Environment → Agent → Model options for the draft form, resolved
 * SERVER-side (env keys ∩ each agent's drivable providers) and refetched
 * whenever the chosen environment changes. A failed fetch degrades to no
 * options — the form disables create rather than guessing.
 */
export function useWorkerFormOptions(environment: string) {
  const [agents, setAgents] = useState<AgentOptionsView[]>([]);

  useEffect(() => {
    if (environment === '') {
      setAgents([]);
      return;
    }
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(
          `/api/workers/form-options?environment=${encodeURIComponent(environment)}`,
        );
        if (!res.ok) {
          if (!cancelled) setAgents([]);
          return;
        }
        const data = (await res.json()) as { agents: AgentOptionsView[] };
        if (!cancelled) setAgents(data.agents ?? []);
      } catch {
        if (!cancelled) setAgents([]);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [environment]);

  return { agents };
}

/**
 * The Workers page's data feed: list on mount, dumb create/remove that
 * POST/DELETE raw fields for the server to validate, and MANUAL probes —
 * `probe`/`reload` run only when the user asks (per-row Re-check /
 * top-bar Reload); nothing probes on mount and nothing polls.
 */
export function useWorkers() {
  const [workers, setWorkers] = useState<WorkerView[]>([]);
  const [probes, setProbes] = useState<Record<string, WorkerProbeView>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async (): Promise<WorkerView[]> => {
    try {
      const res = await fetch('/api/workers');
      if (!res.ok) {
        setError(`Failed to load workers (HTTP ${res.status})`);
        return [];
      }
      const data = (await res.json()) as { workers: WorkerView[] };
      const list = data.workers ?? [];
      setWorkers(list);
      // Prune probe results for names no longer listed — a deleted-then-
      // recreated worker must not inherit its predecessor's status.
      setProbes((prev) =>
        Object.fromEntries(
          Object.entries(prev).filter(([name]) => list.some((w) => w.name === name)),
        ),
      );
      setError(null);
      return list;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load workers');
      return [];
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Shared submit for create (POST /api/workers) and update
  // (PUT /api/workers/:name): the body is sent raw for the server to run
  // its triple validation (environment × agent × model); the hook stays
  // dumb, reporting the server's { ok, error } and refreshing on success.
  const submitWorker = useCallback(
    async (
      method: 'POST' | 'PUT',
      url: string,
      body: unknown,
    ): Promise<{ ok: boolean; error?: string }> => {
      try {
        const res = await fetch(url, {
          method,
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        if (!res.ok) {
          const errBody = (await res.json().catch(() => ({}))) as { error?: string };
          return { ok: false, error: errBody.error ?? `HTTP ${res.status}` };
        }
      } catch (err) {
        return {
          ok: false,
          error: err instanceof Error ? err.message : 'Failed to save worker',
        };
      }
      await refresh();
      return { ok: true };
    },
    [refresh],
  );

  const create = useCallback(
    (input: CreateWorkerInput) => submitWorker('POST', '/api/workers', input),
    [submitWorker],
  );

  // Edit keys on the name PARAMETER (the route), so the body carries only
  // the mutable fields — a rename is not expressible here (the server's
  // patch parser ignores a body name). The edit panel therefore LOCKS the
  // name; true rename waits on worker uuids (ADR-0027 / worker-uuid-identity).
  const update = useCallback(
    (name: string, input: Omit<CreateWorkerInput, 'name'>) =>
      submitWorker('PUT', `/api/workers/${encodeURIComponent(name)}`, input),
    [submitWorker],
  );

  const remove = useCallback(
    async (name: string): Promise<void> => {
      try {
        const res = await fetch(`/api/workers/${encodeURIComponent(name)}`, {
          method: 'DELETE',
        });
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          setError(body.error ?? `Failed to delete ${name} (HTTP ${res.status})`);
          return;
        }
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : `Failed to delete ${name}`);
        return;
      }
      await refresh();
    },
    [refresh],
  );

  const probe = useCallback(async (name: string): Promise<void> => {
    try {
      const res = await fetch(`/api/workers/${encodeURIComponent(name)}/probe`, {
        method: 'POST',
      });
      if (!res.ok) return; // the row simply stays on its last known status
      const result = (await res.json()) as WorkerProbeView;
      setProbes((prev) => ({ ...prev, [name]: result }));
    } catch {
      // Transport failure leaves the row unprobed — Re-check again.
    }
  }, []);

  /** Top-bar Reload: refetch the list, then probe what it returned. */
  const reload = useCallback(async (): Promise<void> => {
    const list = await refresh();
    await Promise.all(list.map((worker) => probe(worker.name)));
  }, [refresh, probe]);

  return { workers, probes, loading, error, refresh, create, update, remove, probe, reload };
}
