import { useState, useEffect, useCallback } from 'react';
import type { TelemetryEvent } from '@magic-ingredients/tiny-brain-core';
import { sseManager, type SSEEvent } from '../services/SSEManager';

interface UseRepoTelemetryResult {
  readonly events: TelemetryEvent[];
  readonly loading: boolean;
  readonly error: string | null;
}

/**
 * Stable dedup key for a telemetry event. The UUIDv7 `id` is the identity:
 * every emit path now stamps one (EventLog.append, and the pipeline-service
 * sites via appendPipelineEvent — live-frontier-projection F3-T2). The content
 * fingerprint is a defensive fallback for any legacy id-less event still in an
 * un-compacted log, so a re-delivered copy of the same physical event dedups
 * rather than doubling the feed.
 */
function eventKey(event: TelemetryEvent): string {
  return event.id ?? JSON.stringify(event);
}

/**
 * One repo-wide live telemetry feed shared by every task-scoped consumer
 * (the plan pills, the task timeline). It does the initial `events.jsonl`
 * read once and then keeps itself fresh from the `telemetryChange` SSE
 * stream, so a pre-commit phase change (e.g. `phase.entered{red}`, which
 * lands no git commit and so never invalidates the plans list) still
 * surfaces immediately — without each task firing its own fetch.
 *
 * Callers derive their per-task overlay from `events` with the core
 * `deriveTaskStateFromEvents`, filtering on the task's ref. Git stays the
 * source of truth for status/SHAs; this feeds the live overlay only.
 */
export function useRepoTelemetry(repoId: string | null): UseRepoTelemetryResult {
  const [events, setEvents] = useState<TelemetryEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!repoId) return;

    let cancelled = false;
    setLoading(true);
    setError(null);
    setEvents([]);

    fetch(`/api/repos/${encodeURIComponent(repoId)}/telemetry`)
      .then(async (res) => {
        if (cancelled) return;
        // 404 = unknown repo: treat as an empty feed rather than an error.
        // (A known repo with an empty log returns 200 with `events: []`.)
        if (res.status === 404) {
          setEvents([]);
          return;
        }
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          throw new Error(body.error ?? `Failed to fetch telemetry (${res.status})`);
        }
        const data = (await res.json()) as { events?: TelemetryEvent[] };
        setEvents(data.events ?? []);
      })
      .catch((err: Error) => {
        if (cancelled) return;
        setEvents([]);
        setError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [repoId]);

  const handleSSE = useCallback((sseEvent: SSEEvent) => {
    if (sseEvent.type !== 'telemetryChange') return;
    if (sseEvent.repoId !== repoId) return;
    // Dedupe re-delivered events — the SSE stream can re-deliver an event
    // already in the feed (filewatcher tick, reconnect, batch replay). Key on
    // the stable `id` (every emit path now stamps one), with a content
    // fingerprint fallback for any legacy id-less event. A re-read of the same
    // physical event is byte-identical, so its key is stable across redelivery;
    // distinct events keep distinct ids, so neither doubles nor false-dedups.
    const incoming = sseEvent.event;
    const incomingKey = eventKey(incoming);
    setEvents(prev =>
      prev.some(e => eventKey(e) === incomingKey) ? prev : [...prev, incoming],
    );
  }, [repoId]);

  useEffect(() => {
    if (!repoId) return;
    const unsubscribe = sseManager.on('telemetryChange', handleSSE);
    return unsubscribe;
  }, [repoId, handleSSE]);

  return { events, loading, error };
}
