import type { HTMLAttributes } from 'react';
import { cn } from '@/lib/utils';

export interface PanelProps extends HTMLAttributes<HTMLDivElement> {
  /** Use the flatter, recessed surface (`panel-flat`) instead of the raised panel. */
  flat?: boolean;
}

/**
 * The core surface primitive from the UI Refresh design system. Renders the
 * raised `panel` surface (white card + soft shadow in light; glassy gradient +
 * blur in dark) or, with `flat`, the recessed `panel-flat` surface. Layout —
 * radius, padding, sizing — is left to the caller via `className`.
 */
export function Panel({ flat = false, className, children, ...rest }: PanelProps) {
  return (
    <div className={cn(flat ? 'panel-flat' : 'panel', className)} {...rest}>
      {children}
    </div>
  );
}

/** Convenience wrapper for the recessed surface — equivalent to `<Panel flat>`. */
export function PanelFlat({ className, children, ...rest }: Omit<PanelProps, 'flat'>) {
  return (
    <Panel flat className={className} {...rest}>
      {children}
    </Panel>
  );
}

export default Panel;
