import React, { useState } from 'react';
import { Header } from './Header';
import { HeaderActionsHostProvider } from './header-actions';
import { Sidebar as AppSidebar, SidebarSection } from './AppSidebar';
import { NotificationsBell } from './NotificationsBell';
import { ProBadge } from './ProBadge';
import ThemeToggle from '../ThemeToggle';
import { useLibrary } from '../../contexts/LibraryContext';
import { useSystemNotifications } from '../../hooks/useSystemNotifications';

interface LayoutProps {
  sidebarSections: SidebarSection[];
  selectedItemId: string | null;
  onItemSelect: (itemId: string) => void;
  children: React.ReactNode;
  /**
   * Optional callback rendering content immediately below a specific
   * sidebar item (e.g. starred repos under the Repos item).
   */
  renderAfterSidebarItem?: (itemId: string) => React.ReactNode;
  /** Bottom-aligned Settings control in the sidebar. */
  onSettingsSelect?: () => void;
  isSettingsSelected?: boolean;
  /** Nav item whose section is active (a child page is open) but not itself selected. */
  activeSectionItemId?: string | null;
}

export const Layout: React.FC<LayoutProps> = ({
  sidebarSections,
  selectedItemId,
  onItemSelect,
  children,
  renderAfterSidebarItem,
  onSettingsSelect,
  isSettingsSelected,
  activeSectionItemId
}) => {
  const [isCollapsed, setIsCollapsed] = useState(false);
  // The top rail's page-actions slot: pages portal their actions (New
  // environment, Reload, ...) into this element via <HeaderActions> (task 11).
  const [actionsHost, setActionsHost] = useState<HTMLElement | null>(null);
  const { connectionStatus, hasCredentials } = useLibrary();
  const libReachable = connectionStatus === 'connected';
  const { notifications } = useSystemNotifications();

  // Find current item for header display
  const currentItem = sidebarSections
    .flatMap(section => section.items)
    .find(item => item.id === selectedItemId);

  return (
    // Sidebar is full-height (it carries the wordmark); the content column to
    // its right holds the per-view header and the scrolling content.
    // Surfaces are transparent so the ambient background wash shows through.
    <div className="flex h-screen overflow-hidden">
      <AppSidebar
        sections={sidebarSections}
        selectedItemId={selectedItemId}
        onItemSelect={onItemSelect}
        isCollapsed={isCollapsed}
        onToggleCollapse={() => setIsCollapsed(!isCollapsed)}
        renderAfterItem={renderAfterSidebarItem}
        onSettingsSelect={onSettingsSelect}
        isSettingsSelected={isSettingsSelected}
        activeSectionItemId={activeSectionItemId}
        headerAccessory={hasCredentials ? <ProBadge libReachable={libReachable} /> : undefined}
        footerNotifications={<NotificationsBell notifications={notifications} />}
        footerTheme={<ThemeToggle tooltipSide={isCollapsed ? 'right' : 'top'} />}
      />

      <div id="content-region" className="relative flex min-w-0 flex-1 flex-col overflow-hidden">
        <Header currentItem={currentItem} onActionsHost={setActionsHost} />

        <main className="flex-1 overflow-auto">
          <HeaderActionsHostProvider value={actionsHost}>{children}</HeaderActionsHostProvider>
        </main>
      </div>
    </div>
  );
};