import React from 'react';
import { Card, CardContent } from '@/components/ui/card';
import type { Feature } from '../types';
import TaskRow from '@/features/tasks/components/TaskRow';
import { usePipelineConfig } from '../hooks/usePipelineConfig';
import { deriveEffectiveStatus, deriveFeatureWorktreeRef, deriveFeatureEffectiveStatus } from '../utils/effective-task-status';
import { formatTaskComponentSlug } from '../utils/task-slug-path';

interface FeatureDetailProps {
  feature: Feature;
  repoId: string;
  /**
   * The owning PRD's id. Required to build each manual task's
   * `manualCompleteContext` — without it the "Mark complete" affordance can't
   * target the `/plans/:planId/...` endpoint, so it stays hidden. Optional
   * because not every caller is plan-scoped.
   */
  planId?: string;
}

const FeatureDetail: React.FC<FeatureDetailProps> = ({ feature, repoId, planId }) => {
  const { pipeline: reviewPipeline } = usePipelineConfig(repoId);
  // When every task's work lives on the same worktree, show it once here so the
  // rows stay clean; a task overriding to a different worktree still shows its
  // own pill (multi-ref-projection / feature-header-worktree-consolidation).
  const featureWorktreeRef = deriveFeatureWorktreeRef(feature.tasks ?? []);
  // Count by worktree-aware effective status, and roll the feature's own status
  // up the same way, so a feature whose work is done on a worktree reads done.
  const effStatuses = (feature.tasks ?? []).map((t) => deriveEffectiveStatus(t).status);
  const completedTasks = effStatuses.filter((s) => s === 'completed').length;
  const supersededTasks = effStatuses.filter((s) => s === 'superseded').length;
  const doneTasks = completedTasks + supersededTasks;
  const totalTasks = feature.tasks?.length || 0;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  const effectiveFeatureStatus = deriveFeatureEffectiveStatus(feature.tasks ?? []);

  return (
    <div>

      {/* Feature Description */}
      {feature.description && (
        <div className="border-b border-border px-4 py-3">
          <p className="text-sm text-muted-foreground">{feature.description}</p>
        </div>
      )}

      {/* Tasks list — plain rows separated by hairline dividers (mockup
          feat-body). No "Tasks" heading; the worktree marker lives only in the
          feature header (PlanDetailsPRD) but featureWorktreeRef is still passed
          to each TaskRow so per-task pills suppress when the whole feature is on
          one worktree. */}
      {totalTasks > 0 ? (
        <div className="divide-y divide-border dark:divide-[oklch(0.5_0.06_282/0.2)]">
          {feature.tasks?.map((task, index) => (
            <TaskRow
              key={task.id}
              task={task}
              repoId={repoId}
              reviewPipeline={reviewPipeline}
              slugPath={formatTaskComponentSlug(index + 1)}
              featureWorktreeRef={featureWorktreeRef}
              manualCompleteContext={
                planId
                  ? { planId, featureId: feature.id, taskNumber: index + 1 }
                  : undefined
              }
            />
          ))}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground px-4 py-4">
          No tasks defined for this feature
        </p>
      )}

      {/* Feature Timeline */}
      {(feature.startedAt || feature.completedAt) && (
        <Card>
          <CardContent className="pt-4">
            <div className="relative">
              {/* Progress percentage above the bar */}
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs text-muted-foreground">Progress</span>
                <span className="text-sm font-semibold">{progress}%</span>
              </div>

              {/* Timeline bar - matching sidebar style */}
              <div className="relative h-2 rounded-full overflow-hidden bg-gray-200 dark:bg-gray-700">
                <div
                  className="absolute inset-y-0 left-0 transition-all duration-300"
                  style={{
                    width: `${feature.completedAt ? 100 : progress}%`,
                    backgroundColor: effectiveFeatureStatus === 'completed' ? '#10b981' :
                                   effectiveFeatureStatus === 'in_progress' ? '#3b82f6' : '#9ca3af'
                  }}
                />
              </div>

              {/* Timeline dates below bar */}
              <div className="flex justify-between mt-3 text-xs text-muted-foreground">
                {feature.startedAt && (
                  <span>{new Date(feature.startedAt).toLocaleDateString()}</span>
                )}
                {feature.completedAt && (
                  <span>{new Date(feature.completedAt).toLocaleDateString()}</span>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default FeatureDetail;
