import React, { useEffect, useState } from 'react';
import { Bot, Check, ChevronDown, Cloud, Copy, HardDrive, Terminal, Zap } from 'lucide-react';
import { GlyphChip, TwoLineTip } from './glyph-chip';

/**
 * The rail's idle-state [Launch ▾] (workers PRD, item-launch-rail
 * tasks 3 + 4): nothing is staffed on this item yet, so the rail offers
 * the two-branch staffing menu instead of empty space.
 *
 * - WORKER branch: pick a dispatchable worker (each row carries the
 *   environment its `worker.environment` resolves to) and POST the
 *   dispatch — the control then transitions to the live worker state
 *   (bot glyph + run id) with the trigger gone, so a second dispatch is
 *   unrepresentable; while a dispatch is starting every row is disabled.
 * - USER branch: "Copy launch command" copies the core-emitted go
 *   string fetched from the item-launch route (never spelled here).
 *
 * Presentational beyond its own lazy fetches: dumb to status/run
 * gating — hosts decide whether to render it at all.
 */
export interface LaunchTarget {
  repoId: string;
  /** The work item as a work-ref slug (fix:x · prd:x/y · spike:x). */
  item: string;
}

/** One dispatchable worker as the menu consumes it (effort stays server-side). */
interface DispatchableWorker {
  name: string;
  model: string;
  environment: string;
  where: 'local' | 'remote';
}

type DispatchPhase =
  | { phase: 'idle' }
  | { phase: 'starting' }
  | { phase: 'dispatched'; worker: DispatchableWorker; runId: string };

const LaunchControl: React.FC<LaunchTarget> = ({ repoId, item }) => {
  const [open, setOpen] = useState(false);
  const [command, setCommand] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  const [copied, setCopied] = useState<'idle' | 'copied' | 'failed'>('idle');
  const [workers, setWorkers] = useState<DispatchableWorker[] | null>(null);
  const [workersFailed, setWorkersFailed] = useState(false);
  const [dispatch, setDispatch] = useState<DispatchPhase>({ phase: 'idle' });
  const [dispatchError, setDispatchError] = useState<string | null>(null);

  const base = `/api/repos/${encodeURIComponent(repoId)}/launch`;

  // Fetch lazily on first open — a closed control costs nothing. A failed
  // fetch is NOT terminal: each reopen re-runs the effect and retries, so a
  // transient failure never dead-ends the menu.
  useEffect(() => {
    if (!open || command !== null) return;
    setFailed(false);
    let cancelled = false;
    void (async () => {
      try {
        // This is the "Run yourself in a local worktree" affordance, so the
        // copied command is the --local base — request it explicitly rather
        // than leaning on the route's remote default.
        const res = await fetch(`${base}/command?item=${encodeURIComponent(item)}&where=local`);
        if (!res.ok) {
          if (!cancelled) setFailed(true);
          return;
        }
        const data = (await res.json()) as { command?: string };
        if (cancelled) return;
        if (typeof data.command === 'string') {
          setCommand(data.command);
        } else {
          setFailed(true);
        }
      } catch {
        if (!cancelled) setFailed(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, command, base, item]);

  // The Worker branch's rows, fetched the same lazy way. A failed fetch
  // flags an explicit unavailable state (never a stuck "Loading…") and
  // retries on the next open, mirroring the command fetch above.
  useEffect(() => {
    if (!open || workers !== null) return;
    setWorkersFailed(false);
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(`${base}/workers`);
        if (!res.ok) {
          if (!cancelled) setWorkersFailed(true);
          return;
        }
        const data = (await res.json()) as { workers?: DispatchableWorker[] };
        if (!cancelled) setWorkers(data.workers ?? []);
      } catch {
        if (!cancelled) setWorkersFailed(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, workers, base]);

  const copy = async (value: string) => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied('copied');
    } catch {
      // Permissions / insecure context — say so instead of silently
      // swallowing the rejection; the command stays visible to select.
      setCopied('failed');
    }
  };

  const dispatchWorker = async (worker: DispatchableWorker) => {
    if (dispatch.phase !== 'idle') return; // double-dispatch guard
    setDispatch({ phase: 'starting' });
    setDispatchError(null);
    try {
      const res = await fetch(`${base}/dispatch`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ item, workerName: worker.name }),
      });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        setDispatchError(body.error ?? `Dispatch failed (HTTP ${res.status})`);
        setDispatch({ phase: 'idle' });
        return;
      }
      const data = (await res.json()) as { runId?: string };
      setDispatch({
        phase: 'dispatched',
        worker,
        runId: typeof data.runId === 'string' ? data.runId : 'run pending',
      });
    } catch (err) {
      setDispatchError(err instanceof Error ? err.message : 'Dispatch failed');
      setDispatch({ phase: 'idle' });
    }
  };

  // Dispatched: the control transitions to the live worker state — the rail's
  // glyph language (bot + env + run id) until the server projection takes
  // over on the next data refresh. The trigger is gone: no double-dispatch.
  if (dispatch.phase === 'dispatched') {
    const { worker, runId } = dispatch;
    const EnvIcon = worker.where === 'remote' ? Cloud : HardDrive;
    return (
      <div
        className="inline-flex items-center gap-1.5"
        onClick={(e) => e.stopPropagation()}
        data-testid="launch-dispatched"
      >
        <span className="font-mono text-[11px] text-muted-foreground">{runId}</span>
        {/* Same shadcn-tooltip glyphs as the MiniStatusRail — worker name over
            model, env name — so the dispatched state speaks the rail's tooltip
            language, not a native title=. */}
        <GlyphChip label={worker.name} tooltip={<TwoLineTip title={worker.name} detail={worker.model} />}>
          <Bot className="h-4 w-4" />
        </GlyphChip>
        <GlyphChip label={worker.environment}>
          <EnvIcon className="h-4 w-4" />
        </GlyphChip>
      </div>
    );
  }

  return (
    // The control lives inside hosts that may themselves be clickable.
    // Every interaction here must stay inside the control — opening the
    // menu, copying, or dispatching must never also fire the host.
    <div className="relative inline-flex" onClick={(e) => e.stopPropagation()}>
      <button
        type="button"
        data-testid="launch-trigger"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => {
          // A stale rejection from a previous attempt must not greet the
          // next open.
          setDispatchError(null);
          setOpen((v) => !v);
        }}
        className="inline-flex items-center gap-1 rounded-lg bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_12%,transparent)] px-2 py-0.5 font-mono text-[11px] font-semibold text-[var(--ds-primary,#8b7cf6)] shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--ds-primary,#8b7cf6)_45%,transparent)] hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_20%,transparent)]"
      >
        <Zap className="h-3 w-3" />
        Launch
        <ChevronDown className="h-3 w-3" />
      </button>
      {open && (
        <div
          role="menu"
          aria-label="Staff this item"
          // The CONTRAST surface (bg-background + strong border), fully
          // opaque: the menu floats over raised .panel areas that share the
          // --ds-panel colour, so a panel-coloured (or translucent) popover
          // fades straight into them.
          className="absolute right-0 top-7 z-50 w-[380px] rounded-xl border border-[var(--ds-border-strong)] bg-background p-2 text-left shadow-xl"
        >
          {workersFailed ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">
              Workers unavailable — reopen to retry.
            </p>
          ) : workers === null ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">Loading…</p>
          ) : workers.length === 0 ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">
              No dispatchable workers — create one on the Workers page.
            </p>
          ) : (
            // Grouped by where the work runs: local machine first, then each
            // remote — the user's mental model is the destination, not the
            // worker registry.
            (['local', 'remote'] as const).map((where) => {
              const group = workers.filter((worker) => worker.where === where);
              if (group.length === 0) return null;
              return (
                <React.Fragment key={where}>
                  <p className="eyebrow px-2 pt-1 pb-1 text-[9px] text-muted-foreground">
                    {where === 'local' ? 'Send to a local worker' : 'Send to a remote worker'}
                  </p>
                  {group.map((worker) => (
                    <button
                      key={worker.name}
                      type="button"
                      aria-label={`Dispatch ${worker.name}`}
                      disabled={dispatch.phase !== 'idle'}
                      onClick={() => void dispatchWorker(worker)}
                      className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_14%,transparent)] disabled:opacity-60 disabled:hover:bg-transparent"
                    >
                      <Bot className="h-4 w-4 shrink-0 text-muted-foreground" />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-semibold leading-tight">
                          {worker.name}
                        </span>
                        <span className="block truncate font-mono text-[11px] text-muted-foreground">
                          {worker.model}
                        </span>
                      </span>
                      <span className="eyebrow inline-flex shrink-0 items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_7%,transparent)] px-1.5 py-0.5 text-[10px] text-muted-foreground">
                        {where === 'remote' ? (
                          <Cloud className="h-3 w-3" />
                        ) : (
                          <HardDrive className="h-3 w-3" />
                        )}
                        {worker.environment}
                      </span>
                    </button>
                  ))}
                </React.Fragment>
              );
            })
          )}
          {dispatchError !== null && (
            <p className="px-2 py-1 text-xs text-[var(--ds-warn,orange)]">{dispatchError}</p>
          )}

          <div className="mt-1.5 border-t border-[var(--ds-border)] pt-1.5">
            <p className="eyebrow px-2 pt-0.5 pb-1 text-[9px] text-muted-foreground">
              Run yourself in a local worktree
            </p>
            {failed ? (
              <p className="px-2 pb-1.5 text-xs text-muted-foreground">
                Launch command unavailable — is the item still tracked?
              </p>
            ) : command === null ? (
              <p className="px-2 pb-1.5 text-xs text-muted-foreground">Loading…</p>
            ) : (
              // Mirrors a worker row: leading icon, the launch command as the
              // flex-1 "thing", and the copy action/state as a trailing chip in
              // the env-chip slot — so the WHOLE row is the copy target, not a
              // stray icon. No command echo: it truncates uselessly here and the
              // clipboard gets the full core-emitted string.
              <button
                type="button"
                onClick={() => void copy(command)}
                className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_14%,transparent)]"
              >
                <Terminal className="h-4 w-4 shrink-0 text-muted-foreground" />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-semibold leading-tight">
                    Launch command
                  </span>
                  <span className="block truncate font-mono text-[11px] text-muted-foreground">
                    tiny-brain go … --local
                  </span>
                </span>
                <span className="eyebrow inline-flex shrink-0 items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_7%,transparent)] px-1.5 py-0.5 text-[10px] text-muted-foreground">
                  {copied === 'copied' ? (
                    <Check className="h-3 w-3" />
                  ) : (
                    <Copy className="h-3 w-3" />
                  )}
                  {copied === 'copied' ? 'Copied' : 'Copy'}
                </span>
              </button>
            )}
            {copied === 'failed' && (
              <p className="px-2 pb-1 text-[11px] text-muted-foreground">
                Copy failed — select the command text instead
              </p>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default LaunchControl;
