import type { CSSProperties, ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { Tooltip, TooltipContent, TooltipTrigger } from './ui/tooltip';

/**
 * A TDD pipeline phase. Each maps to a `--color-phase-*` design token that
 * tints the chip and its dot. `extra` covers any catalog gate beyond the core
 * red/green/review/refactor set (e.g. a docs or mutation step).
 */
export type ChipPhase = 'red' | 'green' | 'review' | 'refactor' | 'extra';

/**
 * The three legible chip states from the mockups: `done` (filled in the phase
 * colour), `current` (the live phase — ring + pulsing dot), and the faint
 * dashed `pending`/`skipped` (not run / skipped). `done` is the default.
 */
export type ChipState = 'done' | 'current' | 'pending' | 'skipped';

const PHASE_VAR: Record<ChipPhase, string> = {
  red: 'var(--color-phase-red)',
  green: 'var(--color-phase-green)',
  review: 'var(--color-phase-review)',
  refactor: 'var(--color-phase-refactor)',
  extra: 'var(--color-phase-extra)',
};

export interface PipelineChipProps {
  /** Chip label (e.g. "Red", "Green", "Review"). May include extra spans. */
  label: ReactNode;
  /** Phase colour for the chip and its dot. Omit for a neutral chip. */
  phase?: ChipPhase;
  /** Visual state — defaults to `done`. */
  state?: ChipState;
  /** Tooltip text (carries the SHA), shown via a shadcn Tooltip and mirrored
   *  onto the chip's `aria-label`. */
  title?: string;
  /** When provided the chip renders as an interactive button. */
  onClick?: () => void;
  /** A second dot in a different phase colour (the review+refactor chip). */
  secondaryPhase?: ChipPhase;
  className?: string;
}

/**
 * The commit-pipeline chip — the signature per-task element. A pill carrying a
 * phase-coloured dot and a label, themed via the `--phase` custom property so a
 * single `.chip` class renders every phase colour. The tooltip text is shown in
 * a shadcn Tooltip on hover/focus (and mirrored onto `aria-label`); the chip
 * becomes a button when `onClick` is supplied.
 */
export function PipelineChip({
  label,
  phase,
  state = 'done',
  title,
  onClick,
  secondaryPhase,
  className,
}: PipelineChipProps) {
  const style = phase ? ({ '--phase': PHASE_VAR[phase] } as CSSProperties) : undefined;
  const classes = cn('chip', state !== 'done' && state, className);
  const content = (
    <>
      <span className="cdot" aria-hidden="true" />
      {secondaryPhase && (
        <span
          className="cdot"
          aria-hidden="true"
          style={{ '--phase': PHASE_VAR[secondaryPhase] } as CSSProperties}
        />
      )}
      {label}
    </>
  );

  const chip = onClick ? (
    <button type="button" className={classes} style={style} aria-label={title} onClick={onClick}>
      {content}
    </button>
  ) : (
    // role="img" makes the aria-label an effective accessible name on the
    // otherwise role-less span (the dots are decorative) — same treatment the
    // prior emoji pills used.
    <span className={classes} style={style} aria-label={title} role={title ? 'img' : undefined}>
      {content}
    </span>
  );

  if (!title) {
    return chip;
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>{chip}</TooltipTrigger>
      <TooltipContent>{title}</TooltipContent>
    </Tooltip>
  );
}

export default PipelineChip;
