import type { StatusTone } from '../components/StatusPill';

/** `16` → `ADR-0016` — the padded reference the ADR files themselves use. */
export function adrRef(number: number): string {
  return `ADR-${String(number).padStart(4, '0')}`;
}

/** Map an ADR lifecycle status onto a status-pill tone. Unknown → gray. */
export function statusTone(status: string): StatusTone {
  switch (status.toLowerCase()) {
    case 'accepted':
      return 'green';
    case 'proposed':
      return 'blue';
    case 'deprecated':
      return 'orange';
    case 'superseded':
      return 'purple';
    default:
      return 'gray';
  }
}

export interface AdrFrontmatter {
  /** Raw scalar frontmatter values by key (quotes stripped, `null` dropped). */
  readonly meta: Readonly<Record<string, string>>;
  /** `tags: [a, b]` parsed to a list; empty when absent. */
  readonly tags: readonly string[];
  /** The markdown body with the frontmatter block removed. */
  readonly body: string;
}

/** Strip a surrounding quote pair, if any. */
function unquote(value: string): string {
  const m = value.match(/^(["'])(.*)\1$/);
  return m ? m[2] : value;
}

/**
 * Split an ADR document into its YAML frontmatter and markdown body. The
 * parser is deliberately minimal — flat `key: value` scalars plus the one
 * list shape (`tags: [a, b]`) the ADR template uses — because the detail
 * header only surfaces those fields; unknown shapes are simply dropped.
 * `null`/empty values are omitted so absent metadata renders nothing.
 * CRLF documents parse the same as LF ones.
 *
 * Contract for malformed input: an opening `---` with no closing fence is
 * NOT frontmatter (it may be a legitimate thematic break), so the whole
 * content is returned as body verbatim rather than best-effort stripped —
 * a truncated file degrades to visible-but-raw, never to silently eaten
 * content.
 */
export function splitAdrFrontmatter(content: string): AdrFrontmatter {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
  if (!match) return { meta: {}, tags: [], body: content };

  const meta: Record<string, string> = {};
  let tags: string[] = [];
  for (const line of match[1].split(/\r?\n/)) {
    const kv = line.match(/^([A-Za-z_][\w-]*):\s*(.*)$/);
    if (!kv) continue;
    const [, key, rawValue] = kv;
    const value = unquote(rawValue.trim());
    if (value === '' || value === 'null') continue;
    const list = value.match(/^\[(.*)\]$/);
    if (list) {
      if (key === 'tags') {
        tags = list[1]
          .split(',')
          .map((t) => unquote(t.trim()))
          .filter((t) => t.length > 0);
      }
      continue;
    }
    meta[key] = value;
  }
  return { meta, tags, body: content.slice(match[0].length) };
}

/**
 * Hoist a LEADING `# ` heading out of the body (the ADR's own title line) so
 * the header renders it exactly once. A document whose first block is not an
 * h1 keeps its body untouched and reports no title.
 */
export function hoistLeadingTitle(body: string): { title: string | null; body: string } {
  const match = body.match(/^\s*# (.+)/);
  if (!match) return { title: null, body };
  // The regex is ^-anchored without the m flag, so the match starts at 0.
  return {
    title: match[1].trim(),
    body: body.slice(match[0].length),
  };
}
