import React from 'react';
import { FileCode2, ScrollText } from 'lucide-react';
import { cn } from '@/lib/utils';
import StatusPill from './StatusPill';
import type { Adr } from '../services/api';
import { adrRef, statusTone } from '../utils/adr-presentation';

export interface DecisionsListProps {
  adrs: Adr[];
  /** The slug of the selected ADR (from the URL), or null when none is chosen. */
  selectedSlug: string | null;
  onSelect: (slug: string) => void;
}

function assetsLabel(n: number): string {
  return `${n} ${n === 1 ? 'asset' : 'assets'}`;
}

/**
 * The Decisions sidebar (adr-browser / decisions-list-detail-ui Task 1). A row
 * per ADR — its ADR-NNNN ref, title, and status pill — with an asset indicator
 * on the rows that carry design assets. Lists EVERY ADR, not just those
 * with assets (the "list-all implies readable" fix for the 2-of-31 gallery).
 * Presentational: selection is URL-driven upstream; this only reflects
 * selectedSlug and reports clicks via onSelect.
 */
const DecisionsList: React.FC<DecisionsListProps> = ({ adrs, selectedSlug, onSelect }) => {
  if (adrs.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 px-4">
        <ScrollText className="h-12 w-12 text-muted-foreground mb-3" aria-hidden="true" />
        <p className="text-text-secondary text-center">No decisions found</p>
        <p className="text-text-tertiary text-sm text-center mt-2">
          Add ADRs under <code className="font-mono">docs/adr/</code>
        </p>
      </div>
    );
  }

  return (
    <ul className="p-3 space-y-1.5" aria-label="Decisions">
      {adrs.map((adr) => {
        const isSelected = adr.slug === selectedSlug;
        return (
          <li key={adr.slug}>
            <button
              type="button"
              onClick={() => onSelect(adr.slug)}
              aria-current={isSelected ? 'true' : undefined}
              className={cn(
                'group flex w-full items-start gap-3 rounded-xl border p-3 text-left transition-colors',
                isSelected
                  ? 'border-border-strong bg-foreground/5'
                  : 'border-border hover:border-border-strong hover:bg-foreground/5',
              )}
            >
              <span className="grid h-8 w-8 flex-none place-items-center rounded-lg bg-primary/10 text-primary">
                <ScrollText className="h-4 w-4" />
              </span>
              <span className="flex min-w-0 flex-1 flex-col gap-1">
                <span className="mono text-[11px] uppercase tracking-wider text-subtle">{adrRef(adr.number)}</span>
                <span className="line-clamp-2 text-sm font-medium leading-snug text-foreground">{adr.title}</span>
                <span className="mt-0.5 flex items-center gap-2">
                  <StatusPill tone={statusTone(adr.status)} label={adr.status} />
                  {adr.hasAssets && (
                    <span
                      className="inline-flex items-center gap-1 text-xs text-muted-foreground"
                      aria-label={assetsLabel(adr.assetCount)}
                    >
                      <FileCode2 className="h-3.5 w-3.5" aria-hidden="true" /> {adr.assetCount}
                    </span>
                  )}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
};

export default DecisionsList;
