import { Fragment } from 'react';
import { Plane } from 'lucide-react';
import { cn } from '@/lib/utils';
import { RAIL_CONTROL, RAIL_HOVER, RAIL_SELECTED } from './railControls';

/** The three parallel work areas surfaced as sibling tabs. */
export type WorkArea = 'plans' | 'fixes' | 'spikes';

export interface WorkAreaCount {
  /** Items currently in progress. */
  inProgress: number;
  /** Total — every item except archived ones (completed/superseded items
   *  still count; only archived, hidden-by-default items are excluded). */
  total: number;
}

/**
 * The three-part In-flight control count: everything in progress, everything
 * waiting on a merge decision, and everything that failed — the one glance that
 * replaces the separate Worktrees ("in progress · to merge") and Runs
 * ("running · failed") counts.
 */
export interface InFlightRailCount {
  /** Deliverables in flight (live runs + inferred interactive sessions). */
  running: number;
  /** Deliverables whose remaining step is a merge decision. */
  toLand: number;
  /** Runs that failed or stalled — the attention signal. */
  failed: number;
}

export interface StageRailProps {
  /**
   * The currently selected work area, or `null` when a non-work-area view
   * (Quality or Settings) is showing and no tab should appear selected.
   */
  activeTab: WorkArea | null;
  /** Select a work area. */
  onTabSelect: (tab: WorkArea) => void;
  /** Per-area counts rendered inside each tab. */
  counts: Record<WorkArea, WorkAreaCount>;
  /**
   * The In-flight control's three-part count. Optional — defaults to zero so the
   * rail renders the control before the board is wired.
   */
  inFlightCount?: InFlightRailCount;
  /** Open the In-flight board. */
  onInFlightSelect?: () => void;
  /** Whether the In-flight board is active (renders the control current). */
  inFlightActive?: boolean;
  className?: string;
}

const TABS: ReadonlyArray<{ area: WorkArea; label: string }> = [
  { area: 'plans', label: 'Plans' },
  { area: 'fixes', label: 'Fixes' },
  { area: 'spikes', label: 'Spikes' },
];

/** One part of a rail count: a value (optionally colour-toned) + label. */
interface CountPart {
  value: number;
  label: string;
  /** Tailwind text-colour utility for the number; omit for default foreground. */
  valueClass?: string;
  /** Pulse the number for attention (e.g. the failed count when > 0). */
  valuePulse?: boolean;
}

function CountSpan({ part }: { part: CountPart }) {
  return (
    <span>
      <span className={cn(part.valueClass, part.valuePulse && 'motion-safe:animate-pulse')}>{part.value}</span>&nbsp;
      <span className="font-sans text-muted-foreground">{part.label}</span>
    </span>
  );
}

/**
 * The shared rail count: middot-separated toned `<value> <label>` parts. Every
 * StageRail control's count (work-area tabs, In-flight) renders from this one
 * component — two parts or three — so they can't drift apart.
 */
function RailCount({ parts }: { parts: readonly CountPart[] }) {
  return (
    <span className="mono flex items-center gap-1 text-[11px] font-normal">
      {parts.map((part, i) => (
        <Fragment key={part.label}>
          {i > 0 && (
            <span className="text-border-strong" aria-hidden="true">
              ·
            </span>
          )}
          <CountSpan part={part} />
        </Fragment>
      ))}
    </span>
  );
}

/**
 * The repo workspace stage rail: the parallel Plans/Fixes/Spikes work-area
 * tablist carrying per-area counts, plus the one In-flight control — the
 * operations board that replaced the separate Worktrees and Runs lenses.
 * Quality and Settings live in the top breadcrumb rail (see RepoViewControls).
 */
export function StageRail({
  activeTab,
  onTabSelect,
  counts,
  inFlightCount = { running: 0, toLand: 0, failed: 0 },
  onInFlightSelect,
  inFlightActive = false,
  className,
}: StageRailProps) {
  // One source of truth for the attention state so the control's flash ring and
  // the failed-count pulse can't drift apart.
  const inFlightFailing = inFlightCount.failed > 0;
  return (
    <section className={cn('px-3 pb-4', className)} aria-label="Plan stages">
      <div className="flex flex-wrap items-center gap-x-2 gap-y-2">
        {/* Parallel tab group (siblings) · grey segmented-control treatment from
            the mockups: a muted container with a raised white pill for the
            active work area. */}
        <div
          role="tablist"
          aria-label="Work areas"
          className="flex items-stretch gap-0.5 rounded-xl border border-border bg-[color-mix(in_oklab,var(--muted),var(--border)_30%)] p-1 text-sm"
        >
          {TABS.map(({ area, label }, index) => {
            const isActive = activeTab === area;
            return (
              <div key={area} className="flex items-stretch">
                {index > 0 && <span className="my-1.5 w-px self-stretch bg-border-strong" aria-hidden="true" />}
                <button
                  type="button"
                  role="tab"
                  aria-selected={isActive}
                  onClick={() => onTabSelect(area)}
                  className={cn(
                    'flex cursor-pointer items-center gap-2.5 rounded-lg px-3 py-1.5 transition-colors',
                    isActive
                      ? 'bg-background font-semibold text-foreground shadow-sm'
                      : 'text-muted-foreground hover:bg-background/70 hover:text-foreground',
                  )}
                >
                  {label}
                  <RailCount
                    parts={[
                      { value: counts[area].total, label: 'total' },
                      { value: counts[area].inProgress, label: 'in progress', valueClass: 'text-blue' },
                    ]}
                  />
                </button>
              </div>
            );
          })}
        </div>

        {/* In-flight control · the one operations board across runs and worktrees,
            with the three-part "N running · M to land · K failed" count. When
            failures need a look it flashes a red attention ring and pulses the
            failed count — the "look now" signal (it replaced the run-attention
            banner, which didn't survive a swarm: one row per failed run). */}
        <button
          type="button"
          onClick={onInFlightSelect}
          aria-current={inFlightActive ? 'page' : undefined}
          className={cn(
            RAIL_CONTROL,
            'gap-2.5 px-3',
            // A visible resting border (not the transparent reserve the work-area
            // tabs use) so the sole non-work-area control reads as its own object.
            inFlightActive ? RAIL_SELECTED : cn('border-border text-muted-foreground', RAIL_HOVER),
            inFlightFailing && 'animate-ring-pulse-red',
          )}
        >
          <Plane className="h-4 w-4" />
          In flight
          <RailCount
            parts={[
              { value: inFlightCount.running, label: 'running', valueClass: 'text-blue' },
              { value: inFlightCount.toLand, label: 'to land', valueClass: 'text-warn' },
              { value: inFlightCount.failed, label: 'failed', valueClass: 'text-red-500', valuePulse: inFlightFailing },
            ]}
          />
        </button>
      </div>
    </section>
  );
}

export default StageRail;
