import { useRef, useState } from 'react';
import { Rocket } from 'lucide-react';
import { SpikeLaunchSnippet } from './SpikeLaunchSnippet';

export interface SpikeLaunchButtonProps {
  repoId: string;
  spikeId: string;
  /** Called after a successful provision so the parent can refetch. */
  onProvisioned?: () => void;
}

type State =
  | { kind: 'idle' }
  | { kind: 'launching' }
  | { kind: 'launched'; worktreePath: string }
  | { kind: 'error'; message: string };

/**
 * The dashboard half of `tb spike launch`: for a doc-only spike (no worktree),
 * POST the provisioning endpoint, then surface the launch snippet inline. Mirrors
 * OrphanedWorktreeBanner's self-contained fetch/loading/error shape.
 *
 * The 409 (already provisioned) case gets a distinct message — the fix is to
 * park, not retry — while any other failure is a generic, retryable error.
 */
export function SpikeLaunchButton({ repoId, spikeId, onProvisioned }: SpikeLaunchButtonProps) {
  const [state, setState] = useState<State>({ kind: 'idle' });
  // Ref guard against a double-POST: the `disabled` attribute only stops a
  // second click AFTER a re-render, but two clicks in the same tick both see the
  // pre-render state. The endpoint is non-idempotent (it provisions a worktree),
  // so a synchronous in-flight latch is the real guard.
  const inFlightRef = useRef(false);

  const handleLaunch = async () => {
    if (inFlightRef.current) return;
    inFlightRef.current = true;
    setState({ kind: 'launching' }); // clears any prior error, so a retry starts clean
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/spikes/${encodeURIComponent(spikeId)}/worktree`,
        { method: 'POST' },
      );
      if (!res.ok) {
        setState({
          kind: 'error',
          message:
            res.status === 409
              ? 'This spike already has a worktree — park it before launching again.'
              : 'Failed to launch the spike worktree.',
        });
        return;
      }
      // Validate the untrusted response shape rather than asserting it — a
      // malformed body must surface an error, never bake `undefined` into the
      // launch command the snippet renders.
      const body: unknown = await res.json();
      const worktreePath =
        typeof body === 'object' && body !== null && 'worktreePath' in body
          ? (body as { worktreePath?: unknown }).worktreePath
          : undefined;
      if (typeof worktreePath !== 'string' || worktreePath.length === 0) {
        setState({ kind: 'error', message: 'Launch succeeded but the server response was malformed.' });
        return;
      }
      setState({ kind: 'launched', worktreePath });
      onProvisioned?.();
    } catch {
      setState({ kind: 'error', message: 'Failed to launch the spike worktree.' });
    } finally {
      inFlightRef.current = false;
    }
  };

  // Once launched, surface the copy-command snippet inline (the parent refetch
  // will also flip worktreeStatus to `present`, which renders the same snippet;
  // showing it here avoids a flash of nothing while that round-trips).
  if (state.kind === 'launched') {
    return <SpikeLaunchSnippet path={state.worktreePath} spikeId={spikeId} />;
  }

  return (
    <div className="flex flex-col gap-2">
      <button
        type="button"
        onClick={handleLaunch}
        disabled={state.kind === 'launching'}
        aria-label="Launch spike worktree"
        className="inline-flex w-fit items-center gap-1.5 rounded-md border border-blue-300 dark:border-blue-600 bg-blue-100 dark:bg-blue-800 px-3 py-1.5 text-xs font-medium text-blue-700 dark:text-blue-200 transition-colors hover:bg-blue-200 dark:hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
      >
        <Rocket className="h-3.5 w-3.5" aria-hidden="true" />
        {state.kind === 'launching' ? 'Launching…' : 'Launch worktree'}
      </button>
      {state.kind === 'error' && (
        <p role="alert" className="text-xs text-red-700 dark:text-red-300">
          {state.message}
        </p>
      )}
    </div>
  );
}
