import React, { useState } from 'react';
import { Cloud, Bot, Activity, SlidersHorizontal } from 'lucide-react';
import { TinyBrainApiSection } from './settings/TinyBrainApiSection';
import { LlmApiSection } from './settings/LlmApiSection';
import { SystemHealthSection } from './settings/SystemHealthSection';
import { GlobalConfigSection } from './settings/GlobalConfigSection';

type SettingsSection = 'tiny-brain-api' | 'llm-api' | 'system-health' | 'configuration';

interface TabDef {
  id: SettingsSection;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

const TABS: readonly TabDef[] = [
  { id: 'system-health', label: 'System Health', icon: Activity },
  { id: 'configuration', label: 'Configuration', icon: SlidersHorizontal },
  { id: 'llm-api', label: 'Local LLM', icon: Bot },
  { id: 'tiny-brain-api', label: 'Tiny Brain API', icon: Cloud },
];

const SettingsPane: React.FC = () => {
  const [activeSection, setActiveSection] = useState<SettingsSection>('system-health');

  const renderContent = () => {
    switch (activeSection) {
      case 'tiny-brain-api':
        return <TinyBrainApiSection />;
      case 'llm-api':
        return <LlmApiSection />;
      case 'system-health':
        return <SystemHealthSection />;
      case 'configuration':
        return <GlobalConfigSection />;
      default:
        return null;
    }
  };

  return (
    <div className="flex h-full flex-col overflow-hidden">
      {/* The "Settings" title lives in the app top rail (layout/Header), not here.
          Top tab bar — section nav runs horizontally so it doesn't stack a second
          sidebar beside the app shell. Matches the repo Settings tab style. */}
      <nav
        data-testid="settings-tabs"
        role="tablist"
        className="flex flex-shrink-0 items-center gap-1 overflow-x-auto border-b border-border px-3"
      >
        {TABS.map((tab) => {
          const isActive = activeSection === tab.id;
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              type="button"
              role="tab"
              id={`settings-tab-${tab.id}`}
              data-testid={`settings-tab-${tab.id}`}
              aria-selected={isActive}
              aria-controls="settings-tabpanel"
              onClick={() => setActiveSection(tab.id)}
              className={`-mb-px flex items-center gap-2 whitespace-nowrap border-b-2 px-3 py-2 text-sm transition-colors ${
                isActive
                  ? 'border-blue text-foreground font-semibold'
                  : 'border-transparent text-muted-foreground hover:text-foreground'
              }`}
            >
              <Icon className="h-4 w-4" />
              {tab.label}
            </button>
          );
        })}
      </nav>

      {/* Content — the tabpanel the active tab controls. */}
      <div
        id="settings-tabpanel"
        role="tabpanel"
        tabIndex={0}
        aria-labelledby={`settings-tab-${activeSection}`}
        className="flex-1 overflow-auto p-4 md:p-6"
      >
        <div className="mx-auto max-w-3xl">{renderContent()}</div>
      </div>
    </div>
  );
};

export default SettingsPane;
