import React, { useState } from 'react';
import { GripVertical, Plus, X, ChevronRight } from 'lucide-react';
import { Tooltip, TooltipTrigger, TooltipContent } from './ui/tooltip';
import { Popover, PopoverTrigger, PopoverContent } from './ui/popover';
import {
  DndContext,
  DragOverlay,
  pointerWithin,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  useDroppable,
  type DragEndEvent,
  type DragStartEvent,
  type CollisionDetection,
} from '@dnd-kit/core';
import {
  SortableContext,
  horizontalListSortingStrategy,
  useSortable,
  arrayMove,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { isStaticAnalyserStep } from '@magic-ingredients/tiny-brain-core/pipeline-normalizer';

interface PipelineEditorProps {
  /** Full pipeline including hook steps and review steps */
  pipeline: PipelineStep[];
  /** All available capability types (active + inactive shown) */
  available: PipelineStep[];
  onSave: (pipeline: PipelineStep[]) => void;
  saving?: boolean;
  showFixedPhases?: boolean;
  /** Show items as parallel (no ordering, no drag) instead of sequential */
  parallel?: boolean;
  /** Hook name for this pipeline (e.g. 'pre-commit'). Enables hook drop zone when set. */
  hookName?: 'pre-commit' | 'pre-push';
  /**
   * Render only one lane of the single `reviewPipeline` value:
   *  - `per-commit` — the static hook steps (run every commit), static-only.
   *  - `per-task`   — the fixed Red/Green TDD phases + the review-gate steps.
   * Both keep the OTHER lane intact on save (no clobber). When unset the editor
   * renders the legacy combined Hooks + Review zones.
   */
  lane?: 'per-commit' | 'per-task';
}

const byLabel = (a: PipelineStep, b: PipelineStep) => (a.label ?? '').localeCompare(b.label ?? '');

/** Add-step popover — the + button with STATIC / AGENTIC sections. */
const AddStepPopover: React.FC<{
  open: boolean;
  onOpenChange: (open: boolean) => void;
  saving?: boolean;
  staticItems: PipelineStep[];
  agenticItems: PipelineStep[];
  /** Types already present (rendered disabled). */
  activeTypes: string[];
  onAdd: (type: string) => void;
  /** When false, the AGENTIC section is hidden (per-commit is static-only). */
  showAgentic?: boolean;
}> = ({ open, onOpenChange, saving, staticItems, agenticItems, activeTypes, onAdd, showAgentic = true }) => (
  <Popover open={open} onOpenChange={onOpenChange}>
    <PopoverTrigger asChild>
      <button
        type="button"
        aria-label="Add step"
        disabled={saving}
        className="pipe-step pipe-step-add transition-colors disabled:cursor-not-allowed disabled:opacity-40"
      >
        <Plus className="h-5 w-5" />
      </button>
    </PopoverTrigger>
    <PopoverContent align="start" className="w-64 p-3 bg-card">
      {staticItems.length === 0 && !(showAgentic && agenticItems.length > 0) && (
        <p className="text-xs text-muted-foreground px-1 py-0.5">No steps available to add.</p>
      )}
      {staticItems.length > 0 && (
        <div className="mb-3">
          <h4 className="text-[11px] font-semibold text-muted-foreground tracking-wider mb-1.5">STATIC ANALYSERS</h4>
          <div className="flex flex-col gap-0.5">
            {staticItems.map((step) => (
              <button
                key={step.type}
                type="button"
                disabled={activeTypes.includes(step.type)}
                onClick={() => onAdd(step.type)}
                className="flex items-center gap-2 px-2 py-1.5 rounded text-sm text-left hover:bg-muted transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <span>{step.emoji}</span>
                <span>{step.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {showAgentic && agenticItems.length > 0 && (
        <div>
          <h4 className="text-[11px] font-semibold text-muted-foreground tracking-wider mb-1.5">AGENTIC ANALYSERS</h4>
          <div className="flex flex-col gap-0.5">
            {agenticItems.map((step) => (
              <button
                key={step.type}
                type="button"
                disabled={activeTypes.includes(step.type)}
                onClick={() => onAdd(step.type)}
                className="flex items-center gap-2 px-2 py-1.5 rounded text-sm text-left hover:bg-muted transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <span>{step.emoji}</span>
                <span>{step.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </PopoverContent>
  </Popover>
);

const FIXED_PHASES = [
  { emoji: '\u{1F534}', label: 'Red TDD Phase' },
  { emoji: '\u{1F7E2}', label: 'Green TDD Phase' },
];

/** The chevron-right flow separator between sequential step tiles (mockup). */
const StepChevron: React.FC = () => (
  <ChevronRight className="h-4 w-4 shrink-0 text-subtle" aria-hidden="true" />
);

/** The fixed Red → Green TDD phase tiles (neutral static tiles, chevron-linked). */
const FixedPhaseTiles: React.FC = () => (
  <>
    {FIXED_PHASES.map((phase, i) => (
      <React.Fragment key={phase.label}>
        {i > 0 && <StepChevron />}
        <Tooltip>
          <TooltipTrigger asChild>
            <li role="listitem" className="pipe-step pipe-step-static cursor-default">
              <span className="pipe-emoji">{phase.emoji}</span>
              <span className="font-medium leading-tight">{phase.label}</span>
            </li>
          </TooltipTrigger>
          <TooltipContent side="bottom">
            <span className="text-xs">TDD phase — disable via enableTDD config</span>
          </TooltipContent>
        </Tooltip>
      </React.Fragment>
    ))}
  </>
);

/** Repo-settings-pipeline tile classes: neutral static vs primary-violet agentic. */
const stepTileClass = (isStatic?: boolean) =>
  `pipe-step ${isStatic ? 'pipe-step-static' : 'pipe-step-agentic'} cursor-pointer`;

// --- Sortable item for active pipeline entries ---
const TollgateBadge: React.FC<{ maxAttempts: number }> = ({ maxAttempts }) => (
  <span data-testid="tollgate-badge" className="pipe-thresh">
    {maxAttempts}x
  </span>
);

const SortableItem: React.FC<{
  id: string;
  label: string;
  emoji: string;
  saving?: boolean;
  isStatic?: boolean;
  isTollgate?: boolean;
  maxAttempts?: number;
  onRemove: () => void;
  onConfigure?: () => void;
}> = ({ id, label, emoji, saving, isStatic, isTollgate, maxAttempts, onRemove, onConfigure }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id, disabled: saving });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    zIndex: isDragging ? 10 : 0,
  };

  return (
    <li
      ref={setNodeRef}
      role="listitem"
      data-active="true"
      data-testid={`step-card-${id}`}
      style={style}
      className={stepTileClass(isStatic)}
      onClick={onConfigure}
    >
      {/* Drag handle (bottom-right, clear of the top-right threshold badge) */}
      <button
        type="button"
        aria-label={`Drag to reorder ${id}`}
        className="absolute bottom-1 right-1 p-0.5 cursor-grab active:cursor-grabbing text-subtle hover:text-muted-foreground"
        {...attributes}
        {...listeners}
      >
        <GripVertical className="h-3 w-3" />
      </button>

      {/* Remove pill */}
      <button
        type="button"
        aria-label={`Remove ${label}`}
        disabled={saving}
        onClick={(e) => { e.stopPropagation(); onRemove(); }}
        className="absolute top-1 left-1 p-0.5 rounded-full text-subtle hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
      >
        <X className="h-3 w-3" />
      </button>

      <span className="pipe-emoji">{emoji}</span>
      <span className="font-medium leading-tight">{label}</span>
      {isTollgate && maxAttempts != null && <TollgateBadge maxAttempts={maxAttempts} />}
    </li>
  );
};

// --- Parallel item (no drag handle) ---
const ParallelItem: React.FC<{
  id: string;
  label: string;
  emoji: string;
  saving?: boolean;
  isStatic?: boolean;
  isTollgate?: boolean;
  maxAttempts?: number;
  onRemove: () => void;
  onConfigure?: () => void;
}> = ({ id, label, emoji, saving, isStatic, isTollgate, maxAttempts, onRemove, onConfigure }) => (
  <li role="listitem" data-active="true" data-testid={`step-card-${id}`} onClick={onConfigure} className={stepTileClass(isStatic)}>
    {/* Remove pill */}
    <button
      type="button"
      aria-label={`Remove ${label}`}
      disabled={saving}
      onClick={(e) => { e.stopPropagation(); onRemove(); }}
      className="absolute top-1 left-1 p-0.5 rounded-full text-subtle hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/30 transition-colors"
    >
      <X className="h-3 w-3" />
    </button>

    <span className="pipe-emoji">{emoji}</span>
    <span className="font-medium leading-tight">{label}</span>
    {isTollgate && maxAttempts != null && <TollgateBadge maxAttempts={maxAttempts} />}
  </li>
);

const ZONE_IDS = new Set(['hook-zone', 'review-zone']);

/**
 * Collision detection: pointerWithin for all targets.
 * Prefers sortable items (for reorder) over zones, but zones are valid drop targets.
 */
const zoneAwareCollision: CollisionDetection = (args) => {
  const hits = pointerWithin(args);
  if (hits.length === 0) return [];

  // Prefer sortable item hits over zone hits (for within-zone reorder)
  const sortableHits = hits.filter(c => !ZONE_IDS.has(c.id as string));
  if (sortableHits.length > 0) return sortableHits;

  // No sortable under pointer — return the zone hit (cross-zone drop)
  return hits.filter(c => ZONE_IDS.has(c.id as string));
};

/** Droppable zone for cross-zone drag */
const DroppableZone: React.FC<{ id: string; children: React.ReactNode; className?: string }> = ({ id, children, className }) => {
  const { setNodeRef, isOver } = useDroppable({ id });
  return (
    <div ref={setNodeRef} className={`${className ?? ''} ${isOver ? 'ring-2 ring-blue ring-dashed rounded-lg' : ''}`}>
      {children}
    </div>
  );
};

export const PipelineEditor: React.FC<PipelineEditorProps> = ({
  pipeline,
  available,
  onSave,
  saving,
  showFixedPhases = true,
  parallel = false,
  hookName,
  lane,
}) => {
  const [popoverOpen, setPopoverOpen] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [configStep, setConfigStep] = useState<string | null>(null);

  // Split pipeline into hook steps (run as git hooks) and review steps (post-commit)
  const hookSteps = pipeline.filter(s => s.hook);
  const reviewSteps = pipeline.filter(s => !s.hook);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor),
  );

  const reviewTypes = reviewSteps.map(s => s.type);
  const hookTypes = new Set(hookSteps.map(s => s.type));
  const availableTypes = available.map(s => s.type);

  const removeReview = (type: string) => {
    onSave([...hookSteps, ...reviewSteps.filter(s => s.type !== type)]);
  };

  /** Remove from hook zone = move to review (strip hook field) */
  const unhook = (type: string) => {
    const step = hookSteps.find(s => s.type === type);
    if (!step) return;
    const { hook: _, ...reviewStep } = step;
    onSave([...hookSteps.filter(s => s.type !== type), ...reviewSteps, reviewStep]);
  };

  const add = (type: string) => {
    const step = available.find(s => s.type === type);
    if (step) {
      onSave([...hookSteps, ...reviewSteps, step]);
      setPopoverOpen(false);
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;

    const activeId = active.id as string;
    const overId = over.id as string;
    const isFromHooks = hookTypes.has(activeId);
    const isFromReview = reviewTypes.includes(activeId);

    // Cross-zone: review → hook zone drop target
    if (isFromReview && overId === 'hook-zone' && hookName) {
      const step = reviewSteps.find(s => s.type === activeId);
      if (step && isStaticAnalyserStep(step)) {
        onSave([...hookSteps, { ...step, hook: hookName }, ...reviewSteps.filter(s => s.type !== activeId)]);
      }
      return;
    }

    // Cross-zone: hook → review zone drop target
    if (isFromHooks && overId === 'review-zone') {
      unhook(activeId);
      return;
    }

    // Same-zone reorder within hooks
    if (isFromHooks && hookTypes.has(overId)) {
      const hookTypesList = hookSteps.map(s => s.type);
      const oldIdx = hookTypesList.indexOf(activeId);
      const newIdx = hookTypesList.indexOf(overId);
      if (oldIdx !== -1 && newIdx !== -1) {
        onSave([...arrayMove(hookSteps, oldIdx, newIdx), ...reviewSteps]);
      }
      return;
    }

    // Same-zone reorder within review
    if (isFromReview) {
      const oldIndex = reviewTypes.indexOf(activeId);
      const newIndex = reviewTypes.indexOf(overId);
      if (oldIndex !== -1 && newIndex !== -1) {
        onSave([...hookSteps, ...arrayMove(reviewSteps, oldIndex, newIndex)]);
      }
    }
  };

  const activeItems = reviewSteps.filter(s => availableTypes.includes(s.type));

  // Split available items into static and agentic for the popover, excluding hook steps
  const popoverAvailable = available.filter(s => !hookTypes.has(s.type));
  const staticItems = popoverAvailable.filter(s => isStaticAnalyserStep(s)).sort(byLabel);
  const agenticItems = popoverAvailable.filter(s => !isStaticAnalyserStep(s)).sort(byLabel);

  // --- Single-lane mode (Per commit / Per task) -------------------------------
  // Both lanes project from the one `pipeline` (reviewPipeline); each edit
  // recombines with the untouched lane so neither is clobbered.
  const addToLane = (type: string) => {
    const step = available.find(s => s.type === type);
    // A type lives in at most one lane — never add a duplicate (the picker also
    // disables active types; this guards the recombine even if that's bypassed).
    if (!step || pipeline.some(s => s.type === type)) return;
    if (lane === 'per-commit') {
      onSave([...hookSteps, { ...step, hook: hookName ?? 'pre-commit' }, ...reviewSteps]);
    } else {
      onSave([...hookSteps, ...reviewSteps, step]);
    }
    setPopoverOpen(false);
  };

  const removeFromLane = (type: string) => {
    if (lane === 'per-commit') {
      onSave([...hookSteps.filter(s => s.type !== type), ...reviewSteps]);
    } else {
      removeReview(type);
    }
  };

  const handleLaneDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const activeId = active.id as string;
    const overId = over.id as string;
    if (lane === 'per-commit') {
      const types = hookSteps.map(s => s.type);
      const o = types.indexOf(activeId), n = types.indexOf(overId);
      if (o !== -1 && n !== -1) onSave([...arrayMove(hookSteps, o, n), ...reviewSteps]);
    } else {
      const o = reviewTypes.indexOf(activeId), n = reviewTypes.indexOf(overId);
      if (o !== -1 && n !== -1) onSave([...hookSteps, ...arrayMove(reviewSteps, o, n)]);
    }
  };

  /** The shared step-config modal (used by both the combined and lane views). */
  const renderConfigPopover = () => {
    if (!configStep) return null;
    const stepIndex = pipeline.findIndex(s => s.type === configStep);
    const step = stepIndex !== -1 ? pipeline[stepIndex] : null;
    if (!step) return null;
    const mode = step.mode ?? 'review';
    const isTollgate = mode === 'tollgate';
    const threshold = step.analyzerThreshold?.min;
    const retries = step.maxAttempts;

    const updateStep = (updates: Partial<PipelineStep>) => {
      const updated = [...pipeline];
      updated[stepIndex] = { ...step, ...updates };
      onSave(updated);
    };

    return (
      <div
        data-testid="step-config-popover"
        className="fixed inset-0 z-50"
        onClick={() => setConfigStep(null)}
      >
        <div
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-card border rounded-lg shadow-lg p-4 w-72"
          onClick={(e) => e.stopPropagation()}
        >
          <h3 className="font-medium text-sm mb-3">{step.label}</h3>
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-medium text-muted-foreground">Mode</span>
              <button
                type="button"
                aria-label={isTollgate ? 'Toggle review' : 'Toggle tollgate'}
                onClick={() => updateStep({ mode: isTollgate ? 'review' : 'tollgate' })}
                className="text-xs px-2 py-0.5 rounded border hover:bg-muted transition-colors"
              >
                {isTollgate ? 'Tollgate' : 'Review'}
              </button>
            </div>
            {isTollgate && (
              <>
                <div>
                  <label htmlFor="step-threshold" className="text-xs font-medium text-muted-foreground">Threshold</label>
                  <input
                    id="step-threshold"
                    type="number"
                    min={0}
                    max={100}
                    defaultValue={threshold ?? ''}
                    onBlur={(e) => {
                      const val = parseInt(e.target.value, 10);
                      if (!isNaN(val) && val >= 0 && val <= 100) updateStep({ analyzerThreshold: { min: val } });
                    }}
                    className="mt-0.5 w-full rounded border px-2 py-1 text-sm"
                  />
                </div>
                <div>
                  <label htmlFor="step-retries" className="text-xs font-medium text-muted-foreground">Max retries</label>
                  <input
                    id="step-retries"
                    type="number"
                    min={1}
                    max={10}
                    defaultValue={retries ?? ''}
                    onBlur={(e) => {
                      const val = parseInt(e.target.value, 10);
                      if (!isNaN(val) && val >= 1 && val <= 10) updateStep({ maxAttempts: val });
                    }}
                    className="mt-0.5 w-full rounded border px-2 py-1 text-sm"
                  />
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );
  };

  // Single-lane view: one row of tiles for the selected lane + its add picker.
  if (lane) {
    const laneSteps = lane === 'per-commit' ? hookSteps : activeItems;
    const showPhases = lane === 'per-task' && showFixedPhases;
    return (
      <>
        <DndContext
          sensors={sensors}
          collisionDetection={pointerWithin}
          onDragStart={(event: DragStartEvent) => setActiveId(event.active.id as string)}
          onDragEnd={(event: DragEndEvent) => { setActiveId(null); handleLaneDragEnd(event); }}
          onDragCancel={() => setActiveId(null)}
        >
          <ul className="flex items-center gap-2 flex-wrap" role="list">
            {showPhases && <FixedPhaseTiles />}

            {parallel ? (
              // Quality runs in parallel — no flow chevrons between tiles.
              laneSteps.map((step) => (
                <ParallelItem
                  key={step.type}
                  id={step.type}
                  label={step.label}
                  emoji={step.emoji}
                  saving={saving}
                  isStatic={isStaticAnalyserStep(step)}
                  isTollgate={step.mode === 'tollgate'}
                  maxAttempts={step.maxAttempts}
                  onRemove={() => removeFromLane(step.type)}
                  onConfigure={() => setConfigStep(step.type)}
                />
              ))
            ) : (
              <SortableContext items={laneSteps.map(s => s.type)} strategy={horizontalListSortingStrategy}>
                {laneSteps.map((step, idx) => (
                  <React.Fragment key={step.type}>
                    {(showPhases || idx > 0) && <StepChevron />}
                    <SortableItem
                      id={step.type}
                      label={step.label}
                      emoji={step.emoji}
                      saving={saving}
                      isStatic={isStaticAnalyserStep(step)}
                      isTollgate={step.mode === 'tollgate'}
                      maxAttempts={step.maxAttempts}
                      onRemove={() => removeFromLane(step.type)}
                      onConfigure={() => setConfigStep(step.type)}
                    />
                  </React.Fragment>
                ))}
              </SortableContext>
            )}

            <AddStepPopover
              open={popoverOpen}
              onOpenChange={setPopoverOpen}
              saving={saving}
              staticItems={staticItems}
              agenticItems={agenticItems}
              activeTypes={lane === 'per-commit' ? pipeline.map(s => s.type) : reviewTypes}
              onAdd={addToLane}
              // The per-commit lane is static-only — agentic reviewers belong on
              // Per task (and the API/normalizer guard would reject them anyway).
              showAgentic={lane !== 'per-commit'}
            />
          </ul>

          <DragOverlay>
            {activeId ? (() => {
              const step = pipeline.find(s => s.type === activeId);
              if (!step) return null;
              return (
                <div className="pipe-step pipe-step-static shadow-lg opacity-90">
              <span className="pipe-emoji">{step.emoji}</span>
              <span className="font-medium leading-tight">{step.label}</span>
            </div>
              );
            })() : null}
          </DragOverlay>
        </DndContext>
        {renderConfigPopover()}
      </>
    );
  }

  return (
    <>
    <DndContext
      sensors={sensors}
      collisionDetection={zoneAwareCollision}
      onDragStart={(event: DragStartEvent) => setActiveId(event.active.id as string)}
      onDragEnd={(event: DragEndEvent) => { setActiveId(null); handleDragEnd(event); }}
      onDragCancel={() => setActiveId(null)}
    >
      {/* Hook zone — always visible when hookName is set */}
      {hookName && (
        <DroppableZone id="hook-zone" className="mb-2">
          <span className="text-[10px] font-semibold text-blue uppercase tracking-wider">Hooks</span>
          {hookSteps.length > 0 ? (
            <ul className="flex items-center gap-2 flex-wrap mt-1 min-h-[76px]" role="list">
              <SortableContext items={hookSteps.map(s => s.type)} strategy={horizontalListSortingStrategy}>
                {hookSteps.map((step) => (
                  <SortableItem
                    key={step.type}
                    id={step.type}
                    label={step.label}
                    emoji={step.emoji}
                    saving={saving}
                    isStatic={isStaticAnalyserStep(step)}
                    onRemove={() => unhook(step.type)}
                  />
                ))}
              </SortableContext>
            </ul>
          ) : (
            <div className="mt-1 h-[76px] px-3 flex items-center justify-center rounded-lg border border-dashed border-blue/40">
              <p className="text-[11px] text-muted-foreground italic">Drag a static analyser here</p>
            </div>
          )}
        </DroppableZone>
      )}

      {/* Review zone */}
      {hookName && (
        <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Review</span>
      )}

      <DroppableZone id="review-zone">
        <ul className="flex items-center gap-2 flex-wrap mt-1" role="list">
          {/* Fixed phases — only shown for commit pipeline */}
          {showFixedPhases && <FixedPhaseTiles />}

          {/* Active items */}
          {parallel ? (
            /* Parallel mode — no ordering, no drag handles, no flow chevrons */
            activeItems.map((step) => (
              <ParallelItem
                key={step.type}
                id={step.type}
                label={step.label}
                emoji={step.emoji}
                saving={saving}
                isStatic={isStaticAnalyserStep(step)}
                isTollgate={step.mode === 'tollgate'}
                maxAttempts={step.maxAttempts}
                onRemove={() => removeReview(step.type)}
                onConfigure={() => setConfigStep(step.type)}
              />
            ))
          ) : (
            <SortableContext items={activeItems.map(s => s.type)} strategy={horizontalListSortingStrategy}>
              {activeItems.map((step, idx) => (
                <React.Fragment key={step.type}>
                  {(showFixedPhases || idx > 0) && <StepChevron />}
                  <SortableItem
                    id={step.type}
                    label={step.label}
                    emoji={step.emoji}
                    saving={saving}
                    isStatic={isStaticAnalyserStep(step)}
                    isTollgate={step.mode === 'tollgate'}
                    maxAttempts={step.maxAttempts}
                    onRemove={() => removeReview(step.type)}
                    onConfigure={() => setConfigStep(step.type)}
                  />
                </React.Fragment>
              ))}
            </SortableContext>
          )}

      {/* Add step button with popover */}
      <AddStepPopover
        open={popoverOpen}
        onOpenChange={setPopoverOpen}
        saving={saving}
        staticItems={staticItems}
        agenticItems={agenticItems}
        activeTypes={reviewTypes}
        onAdd={add}
      />
        </ul>
      </DroppableZone>

      {/* Drag overlay — shows avatar of dragged step */}
      <DragOverlay>
        {activeId ? (() => {
          const step = pipeline.find(s => s.type === activeId);
          if (!step) return null;
          return (
            <div className="pipe-step pipe-step-static shadow-lg opacity-90">
              <span className="pipe-emoji">{step.emoji}</span>
              <span className="font-medium leading-tight">{step.label}</span>
            </div>
          );
        })() : null}
      </DragOverlay>
    </DndContext>

    {/* Step config popover */}
    {renderConfigPopover()}
    </>
  );
};
