import { useEffect, useRef, type ReactNode } from 'react';

interface IslandProps {
  open: boolean;
  onClose: () => void;
  /** Accessible name for the dialog — what this island is showing. */
  ariaLabel: string;
  /**
   * Panel width. `default` caps at `max-w-6xl` (the delivery / task islands);
   * `wide` drops the cap so the panel fills the backdrop's content width
   * responsively — for surfaces that need the horizontal room (asset previews).
   */
  size?: 'default' | 'wide';
  /**
   * Drop the 8vh overlay top gap. For islands composed INLINE in a pane
   * (WorkerRunIsland's mounts: the in-flight board's run detail and the
   * Running-pill drill-down) rather than over a full content region, where
   * the gap reads as dead padding above the surface (fix
   * run-dispatch-stale-dashboard).
   */
  flush?: boolean;
  children: ReactNode;
}

/**
 * The shared overlay shell for full-view islands (worktree-merge delivery, task
 * detail). It is rendered *in place of* the content region's body (not portaled
 * on top of it), so the single app-wide ambient wash shows straight through its
 * transparent backdrop — never replayed. It owns the click/Escape dismiss and the
 * opaque, fixed-height `max-w-6xl` panel; consumers pass only their content and
 * arrange their own pinned (`shrink-0`) and scrolling (`flex-1 min-h-0
 * overflow-y-auto`) sections inside the panel — the page itself never scrolls.
 */
export function Island({ open, onClose, ariaLabel, size = 'default', flush = false, children }: IslandProps) {
  const dialogRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    dialogRef.current?.focus();
    return () => window.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div
      data-testid="island-backdrop"
      role="presentation"
      // Transparent: with the content replaced (nothing opaque behind), the one
      // app wash shows through. A click on the backdrop itself dismisses. Fills
      // its container height with the shared top gap (dropped when flush — an
      // inline pane detail sits at the top), so the page never scrolls.
      className={`grid h-full min-h-0 items-start justify-items-center overflow-hidden px-6 pb-6 ${
        flush ? 'pt-0' : 'pt-[8vh]'
      }`}
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel}
        tabIndex={-1}
        // Opaque .panel card, fixed height (fills to the bottom), flex column so
        // consumers pin sections and scroll only the middle. `wide` drops the
        // max-width cap so the panel fills the backdrop width responsively.
        className={`panel relative flex h-full w-full flex-col overflow-hidden rounded-2xl focus:outline-none ${
          size === 'wide' ? 'max-w-none' : 'max-w-6xl'
        }`}
      >
        {children}
      </div>
    </div>
  );
}
