import React, { useEffect, useState } from 'react';
import { Loader2, FileCode2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import StatusPill from './StatusPill';
import { fetchAdrContent } from '../services/api';
import { adrRef, statusTone, splitAdrFrontmatter, hoistLeadingTitle } from '../utils/adr-presentation';

export interface AdrDetailProps {
  repoId: string;
  /** The selected ADR's slug (docs/adr/<slug>.md). */
  slug: string;
  /** Whether this ADR carries design assets — drives the Assets affordance. */
  hasAssets?: boolean;
  /** Count of assets, shown in the affordance label. */
  assetCount?: number;
  /** Open the ADR's assets (the shared kind-`adr` AssetsIsland). */
  onOpenAssets?: () => void;
}

interface AdrDocumentProps {
  content: string;
  slug: string;
  hasAssets: boolean;
  assetCount: number;
  onOpenAssets?: () => void;
}

/**
 * A fetched ADR document, rendered (fix: decisions-view-readability-and-splitter).
 * Frontmatter never renders verbatim — it becomes the contrast header
 * (ref · status · date · tags) above the prose body, and the body's own
 * leading `# ` title is hoisted up so it renders exactly once. Purely
 * presentational, so the header/hoist behaviour is testable apart from the
 * fetch/loading state around it.
 */
const AdrDocument: React.FC<AdrDocumentProps> = ({ content, slug, hasAssets, assetCount, onOpenAssets }) => {
  const { meta, tags, body: afterMeta } = splitAdrFrontmatter(content);
  const { title, body } = hoistLeadingTitle(afterMeta);
  const number = Number(meta.adr_number ?? /^(\d+)/.exec(slug)?.[1]);

  return (
    <>
      <header data-testid="adr-header" className="mb-4 rounded-xl border border-border bg-foreground/5 p-4">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="flex flex-wrap items-center gap-2.5">
            {Number.isFinite(number) && (
              <span className="mono text-[11px] uppercase tracking-wider text-subtle">{adrRef(number)}</span>
            )}
            {meta.status && <StatusPill tone={statusTone(meta.status)} label={meta.status} />}
            {meta.date && <span className="text-xs text-muted-foreground">{meta.date}</span>}
          </div>
          {hasAssets && assetCount > 0 && onOpenAssets && (
            <button
              type="button"
              onClick={onOpenAssets}
              className="inline-flex items-center gap-1.5 rounded-lg border border-border px-3 py-1.5 text-xs font-medium text-foreground transition-colors hover:border-border-strong hover:bg-foreground/5"
            >
              <FileCode2 className="h-3.5 w-3.5" aria-hidden="true" /> Assets ({assetCount})
            </button>
          )}
        </div>
        <h1 className="display mt-2 text-xl font-semibold leading-snug text-foreground">
          {title ?? meta.title ?? slug}
        </h1>
        {tags.length > 0 && (
          <div className="mt-2.5 flex flex-wrap gap-1.5">
            {tags.map((tag) => (
              <span key={tag} className="rounded-md border border-border px-1.5 py-0.5 text-[11px] text-muted-foreground">
                {tag}
              </span>
            ))}
          </div>
        )}
      </header>
      <div
        data-testid="adr-source"
        className="panel-flat prose prose-sm max-w-none overflow-auto rounded-xl p-4 dark:prose-invert"
      >
        <ReactMarkdown remarkPlugins={[remarkGfm]}>{body}</ReactMarkdown>
      </div>
    </>
  );
};

/**
 * The Decisions detail pane (adr-browser / decisions-list-detail-ui Task 2).
 * Fetches the selected ADR's raw markdown by slug and renders it through the
 * shared markdown renderer (as FixSourceSheet / PlanDetails do), with honest
 * loading / error states. Re-fetches when the slug changes so every selection
 * renders content — no ADR row is a dead end.
 */
const AdrDetail: React.FC<AdrDetailProps> = ({
  repoId,
  slug,
  hasAssets = false,
  assetCount = 0,
  onOpenAssets,
}) => {
  const [content, setContent] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setContent(null);
    setLoading(true);
    setError(null);
    fetchAdrContent(repoId, slug)
      .then((c) => {
        if (!cancelled) setContent(c);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : 'Failed to load decision');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, slug]);

  return (
    <div className="min-h-0 flex-1 overflow-auto p-6">
      {loading ? (
        <p className="flex items-center gap-2 py-4 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" /> Loading decision…
        </p>
      ) : error ? (
        <p role="alert" className="py-4 text-sm text-red-600 dark:text-red-400">
          Couldn&rsquo;t load decision — {error}
        </p>
      ) : content !== null ? (
        <AdrDocument
          content={content}
          slug={slug}
          hasAssets={hasAssets}
          assetCount={assetCount}
          {...(onOpenAssets ? { onOpenAssets } : {})}
        />
      ) : null}
    </div>
  );
};

export default AdrDetail;
