/**
 * Human run duration for the header's `Ran for` vital (fix
 * run-dispatch-stale-dashboard task 13). Settled runs span
 * startedAt → endedAt; live runs span startedAt → now (injectable for
 * tests). Null for unparseable or negative ranges — the vital shows a dash
 * rather than a lie.
 */
export function formatRunDuration(
  startedAt: string,
  endedAt?: string,
  now: Date = new Date(),
): string | null {
  const start = Date.parse(startedAt);
  const end = endedAt !== undefined ? Date.parse(endedAt) : now.getTime();
  if (Number.isNaN(start) || Number.isNaN(end) || end < start) return null;

  // A zero-length RANGE is a real (instant) duration; a zero BUDGET is
  // invalid — hence the special case rather than sharing the null.
  return end === start ? '0s' : formatDurationMs(end - start);
}

/**
 * The same grain rules for a raw millisecond duration — used for the
 * record's computed timeout budget (fix worker-run-timeouts task 3).
 * Null for non-positive or non-finite input rather than a lie.
 */
export function formatDurationMs(ms: number): string | null {
  if (!Number.isFinite(ms) || ms <= 0) return null;
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  if (hours > 0) return `${hours}h ${minutes}m`;
  if (minutes > 0) return `${minutes}m`;
  return `${totalSeconds}s`;
}
