import { useState } from 'react';
import { Trash2 } from 'lucide-react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import type {
  SpikeProgress,
  SpikeProgressTask,
  SpikeStatus,
  SpikeWorktreeStatus,
} from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';
import { Badge } from '@/components/ui/badge';
import CopyIdButton from './CopyIdButton';
import { PanelFlat } from './ui/Panel';
import { StatReadout } from './ui/StatReadout';
import { DetailHeader } from './DetailHeader';
import { SpikeLaunchSnippet } from './SpikeLaunchSnippet';
import { SpikeLaunchButton } from './SpikeLaunchButton';
import { SpikeParkButton } from './SpikeParkButton';
import { SpikeCleanupIsland } from './SpikeCleanupIsland';
import { OrphanedWorktreeBanner } from './OrphanedWorktreeBanner';
import { SpikeOutcomeCapture } from './SpikeOutcomeCapture';
import TaskRow from '@/features/tasks/components/TaskRow';
import { formatTaskComponentSlug } from '../utils/task-slug-path';
import { TimeboxCountdown } from './TimeboxCountdown';
import {
  SPIKE_STATUS_LABEL,
  SPIKE_TERMINAL_STATUSES,
  narrowSpikeStatus,
} from './spike-status';
import type { TaskRowTask } from '../types';
import type {
  PipelineStep,
  ReviewVerdict,
} from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { TelemetryEvent } from '@magic-ingredients/tiny-brain-core';
import { deriveTaskOverlay } from '../utils/telemetry-overlay';

export interface SpikeDetailProps {
  spike: SpikeProgress;
  worktreeStatus: SpikeWorktreeStatus;
  repoId: string;
  /** Repo-wide live telemetry feed, overlaid onto the spike's task rows. */
  telemetry?: readonly TelemetryEvent[];
  onWorktreeCleared?: () => void;
  onWorktreeProvisioned?: () => void;
  onOutcomeRecorded?: () => void;
}

/**
 * Hermetic spike pipeline — see `pipelines/spike.ts` in core. The
 * default spike strategy runs `green → complete` with no review gate,
 * so the dashboard passes an empty pipeline and TaskRow renders just
 * the Green pill per task. Correctness for a spike is captured by the
 * terminal frontmatter status (validated / invalidated / abandoned),
 * not a pipeline review.
 */
const SPIKE_PIPELINE_STEPS: PipelineStep[] = [];

// Lowercase status word for the header eyebrow ("Spike · in progress"),
// mirroring FixDetail. Only the three lifecycle statuses — a terminal spike
// (any verdict) reads as completed; the verdict is not a status.
const SPIKE_EYEBROW_WORD: Record<SpikeStatus, string> = {
  not_started: 'not started',
  in_progress: 'in progress',
  validated: 'completed',
  invalidated: 'completed',
  abandoned: 'completed',
};

// Eyebrow colour per status — live blue for in progress, done for completed,
// neutral otherwise.
const SPIKE_EYEBROW_COLOR: Record<SpikeStatus, string> = {
  not_started: 'text-subtle',
  in_progress: 'text-blue',
  validated: 'text-done',
  invalidated: 'text-done',
  abandoned: 'text-done',
};

/**
 * Map an outcome-table result marker to a badge colour. The well-known
 * tokens (PASS / FAIL / PARTIAL / SKIP) get coloured chips; anything
 * else gets a neutral chip so new vocabulary the author invents on a
 * spike-by-spike basis still renders something readable.
 */
function criterionResultTone(marker: string): string {
  const token = marker.trim().toUpperCase();
  if (token === 'PASS' || token === 'PASSED') {
    return 'border-green-500/40 text-green-600 dark:text-green-400 bg-green-500/10';
  }
  if (token === 'FAIL' || token === 'FAILED') {
    return 'border-red-500/40 text-red-600 dark:text-red-400 bg-red-500/10';
  }
  if (token === 'PARTIAL' || token === 'PARTIALLY') {
    return 'border-amber-500/40 text-amber-600 dark:text-amber-400 bg-amber-500/10';
  }
  if (token === 'SKIP' || token === 'SKIPPED' || token === 'N/A') {
    return 'border-muted-foreground/30 text-muted-foreground';
  }
  return 'border-muted-foreground/30 text-muted-foreground';
}

const VALID_VERDICTS: ReadonlySet<ReviewVerdict> = new Set<ReviewVerdict>([
  'clean',
  'needs-refactoring',
]);

/**
 * SpikeProgressTask carries a wider `verdict?: string` than the
 * dashboard's ReviewRecord (`'clean' | 'needs-refactoring'`). Narrow at
 * the boundary: drop any verdict the renderer doesn't know about rather
 * than smuggle a wider type through with a cast.
 */
function toTaskRowTask(
  task: SpikeProgressTask,
  spikeId: string,
  telemetry: readonly TelemetryEvent[],
): TaskRowTask {
  // Live overlay from the shared telemetry feed (spike task ref), so a
  // pre-commit phase change surfaces on the spike pills without a refetch.
  const derivedState = task.uuid
    ? deriveTaskOverlay(telemetry, { kind: 'spike', spike: spikeId, task: task.uuid })
    : undefined;
  const reviews: TaskRowTask['reviews'] = task.reviews
    ? Object.fromEntries(
        Object.entries(task.reviews).map(([key, value]) => [
          key,
          {
            ...value,
            verdict:
              value.verdict && VALID_VERDICTS.has(value.verdict as ReviewVerdict)
                ? (value.verdict as ReviewVerdict)
                : undefined,
          },
        ]),
      )
    : undefined;
  return {
    ...task,
    status: (task.status as TaskRowTask['status']) ?? 'not_started',
    pipelineType: task.pipelineType ?? 'spike',
    reviews,
    ...(derivedState ? { derivedState } : {}),
  };
}

export function SpikeDetail({
  spike,
  worktreeStatus,
  repoId,
  telemetry = [],
  onWorktreeCleared,
  onWorktreeProvisioned,
  onOutcomeRecorded,
}: SpikeDetailProps) {
  const status = narrowSpikeStatus(spike.status);
  const isTerminal = SPIKE_TERMINAL_STATUSES.has(status);
  const [cleanupOpen, setCleanupOpen] = useState(false);

  // Spikes run the hermetic green→complete pipeline (no review gate), so a
  // task is either done or not — progress is a simple done/total ratio.
  const totalTasks = spike.tasks.length;
  const completedCount = spike.tasks.filter((t) => t.status === 'completed').length;
  const supersededCount = spike.tasks.filter((t) => t.status === 'superseded').length;
  const doneTasks = completedCount + supersededCount;
  const left = totalTasks - doneTasks;
  const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  const progressDetail =
    supersededCount > 0
      ? `${completedCount} done · ${supersededCount} superseded · ${left} left`
      : `${doneTasks} done · ${left} left`;

  return (
    <div className="h-full flex flex-col">
      <div className="flex-1 overflow-y-auto px-7 py-6">
        <div className="mx-auto max-w-4xl space-y-6">

          {/* Header — the shared DetailHeader shell (eyebrow + title + id copy,
              then the status pill / created / task-count meta). A spike has no
              merge/deliver affordance — its worktree is teardown-only, surfaced
              by the cleanup island below — so no rail. */}
          <DetailHeader
            testId="spike-detail-header"
            eyebrow={
              <p data-testid="spike-eyebrow" className={cn('eyebrow text-[10px]', SPIKE_EYEBROW_COLOR[status])}>
                Spike · {SPIKE_EYEBROW_WORD[status]}
              </p>
            }
            title={<h1 className="display text-2xl font-bold leading-snug">{spike.title}</h1>}
            titleAdornment={<CopyIdButton value={spike.id} kind="Spike" className="flex-shrink-0" />}
            meta={
              // The eyebrow already states the lifecycle status (matching the
              // PRD/fix headers), so the header carries no separate status pill.
              <span className="text-sm text-muted-foreground">
                created {new Date(spike.created).toLocaleDateString()}
                {totalTasks > 0 && <> · {totalTasks} {totalTasks === 1 ? 'task' : 'tasks'}</>}
              </span>
            }
          />

          {/* Worktree action. While the spike is live, the copy-command button
              relaunches it. Once it's finished (terminal), the work is done — so
              the copy command is replaced by a Clean up button that opens the
              teardown-only merge surface (delete the worktree, keep the spike). */}
          {worktreeStatus.kind === 'present' && (
            isTerminal ? (
              <button
                type="button"
                data-testid="spike-cleanup-button"
                onClick={() => setCleanupOpen(true)}
                className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground"
              >
                <Trash2 className="h-4 w-4" /> Clean up
              </button>
            ) : (
              // Live spike with a worktree: relaunch (copy command) OR park it
              // (remove the worktree, keep the branch — park clears the field, so
              // onWorktreeCleared is the right refetch).
              <div className="flex flex-wrap items-center gap-2">
                <SpikeLaunchSnippet path={worktreeStatus.path} spikeId={spike.id} />
                <SpikeParkButton
                  repoId={repoId}
                  spikeId={spike.id}
                  onParked={onWorktreeCleared}
                />
              </div>
            )
          )}
          {worktreeStatus.kind === 'present' && isTerminal && (
            <SpikeCleanupIsland
              spikeTitle={spike.title}
              branch={worktreeStatus.branch}
              open={cleanupOpen}
              onClose={() => setCleanupOpen(false)}
            />
          )}
          {worktreeStatus.kind === 'orphaned' && (
            <OrphanedWorktreeBanner
              repoId={repoId}
              spikeId={spike.id}
              branch={worktreeStatus.branch}
              onCleared={onWorktreeCleared}
            />
          )}
          {/* No worktree yet: while the spike is live, offer to provision one on
              demand (the doc-only → launch flow). A terminal spike is finished —
              there is nothing to launch, so no button. */}
          {worktreeStatus.kind === 'unconfigured' && !isTerminal && (
            <SpikeLaunchButton
              repoId={repoId}
              spikeId={spike.id}
              onProvisioned={onWorktreeProvisioned}
            />
          )}

          {/* KPI rail — the design-system StatReadout (gradient bar + done/left
              breakdown), the spike analogue of FixDetail's "Tasks resolved". */}
          {totalTasks > 0 && (
            <StatReadout label="Tasks complete" value={progress} detail={progressDetail} />
          )}

          {/* Question + Timebox — recessed panel-flat sub-panels paired side by
              side (per the mockup): the "why" next to the "how long". */}
          <div className="grid items-start gap-3 sm:grid-cols-2">
            <PanelFlat className="rounded-2xl p-5">
              <p className="eyebrow text-[10px] text-subtle">Question</p>
              <p className="mt-2 whitespace-pre-line text-sm leading-relaxed text-muted-foreground">
                {spike.question}
              </p>
            </PanelFlat>
            <PanelFlat className="rounded-2xl p-5">
              <p className="eyebrow text-[10px] text-subtle">Timebox</p>
              <div className="mt-2">
                <TimeboxCountdown created={spike.created} timebox={spike.timebox} status={status} />
              </div>
            </PanelFlat>
          </div>

          {/* Acceptance criteria — recessed panel, with per-criterion result
              badges once the spike is terminal. */}
          <PanelFlat className="rounded-2xl p-5">
            <p className="eyebrow text-[10px] text-subtle">Acceptance criteria</p>
            <ul data-testid="spike-criteria" className="mt-3 space-y-2 text-sm">
              {spike.acceptanceCriteria.map((criterion, i) => {
                const marker = spike.criterionResults?.[i] ?? null;
                return (
                  <li key={i} className="flex items-start gap-2">
                    <span
                      aria-hidden="true"
                      className="mt-1 inline-block w-1.5 h-1.5 rounded-full bg-purple-400 flex-shrink-0"
                    />
                    <span className="flex-1">{criterion}</span>
                    {marker && (
                      <Badge
                        data-testid="spike-criterion-result"
                        variant="outline"
                        className={cn('text-xs flex-shrink-0', criterionResultTone(marker))}
                      >
                        {marker}
                      </Badge>
                    )}
                  </li>
                );
              })}
            </ul>
          </PanelFlat>

          {/* Outcome capture — shown only while the spike is in_progress. */}
          {status === 'in_progress' && (
            <SpikeOutcomeCapture
              repoId={repoId}
              spikeId={spike.id}
              onCompleted={onOutcomeRecorded}
            />
          )}

          {/* Outcome — terminal-only, mirrors FixDetail's Resolution card. The
              outcomeBody markdown renders inline; older docs fall back to a
              file-pointer hint. */}
          {isTerminal && (
            <PanelFlat data-testid="spike-outcome" data-status={status} className="rounded-2xl p-5">
              <p className="eyebrow text-[10px] text-subtle">Outcome · {SPIKE_STATUS_LABEL[status]}</p>
              <div className="mt-2">
                {spike.outcomeBody ? (
                  <div className="prose prose-sm dark:prose-invert max-w-none text-sm">
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{spike.outcomeBody}</ReactMarkdown>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">
                    See the spike doc body for the outcome narrative
                    (<code className="font-mono">docs/spikes/{spike.id}.md</code>).
                  </p>
                )}
              </div>
            </PanelFlat>
          )}

          {/* Tasks — heading + the shared TaskRow rows in a raised, divided panel
              (same surface as FixDetail). Spikes run green → complete with no
              review gate. */}
          <div>
            <div className="flex flex-wrap items-center justify-between gap-2">
              <h2 className="display text-base font-semibold">Tasks</h2>
              <span className="text-xs text-muted-foreground">
                Spikes run Red → Green only — no review gate.
              </span>
            </div>
            <div className="mt-3">
              {spike.tasks.length === 0 ? (
                <p className="py-4 text-center text-sm text-muted-foreground">
                  No tasks yet — they appear after the first{' '}
                  <code className="font-mono">tb task sync</code>.
                </p>
              ) : (
                <div className="panel divide-y divide-border overflow-hidden rounded-2xl dark:divide-[oklch(0.5_0.06_282/0.2)]">
                  {spike.tasks.map((task, index) => (
                    <TaskRow
                      key={task.id}
                      task={toTaskRowTask(task, spike.id, telemetry)}
                      repoId={repoId}
                      reviewPipeline={SPIKE_PIPELINE_STEPS}
                      slugPath={formatTaskComponentSlug(index + 1)}
                    />
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
