import React from 'react';
import { Tooltip, TooltipContent, TooltipTrigger } from './ui/tooltip';

/** Neutral (non-worktree-purple) chip skin for the runner / environment glyphs.
 *  8px radius to match the status pills + pipeline chips; tight padding so the
 *  glyph reads the same size as the status pill and the worktree chip. */
export const GLYPH_CHIP_CLASS =
  'inline-flex flex-shrink-0 items-center justify-center rounded-lg p-0.5 text-muted-foreground';

/** A glyph wrapped in the shadcn tooltip: the trigger span carries the
 *  aria-label (so it stays reachable by name), and the tooltip content defaults
 *  to that label unless a richer body is supplied. Shared by the MiniStatusRail
 *  and the LaunchControl dispatched state so both speak the same tooltip. */
export const GlyphChip: React.FC<{
  label: string;
  tooltip?: React.ReactNode;
  children: React.ReactNode;
  /** Inline overrides on the trigger — e.g. a failed-run tint. Inline `color`
   *  (not a `text-*` class) so it beats the chip's `text-muted-foreground`
   *  without a Tailwind source-order conflict, matching the repo's other
   *  `--color-warn` consumers. */
  style?: React.CSSProperties;
  /** Optional test id on the trigger, for glyphs a test needs to single out. */
  testId?: string;
}> = ({ label, tooltip, children, style, testId }) => (
  <Tooltip>
    <TooltipTrigger asChild>
      <span aria-label={label} data-testid={testId} style={style} className={GLYPH_CHIP_CLASS}>
        {children}
      </span>
    </TooltipTrigger>
    <TooltipContent side="bottom">{tooltip ?? label}</TooltipContent>
  </Tooltip>
);

/** A two-line tooltip body: a name on top, a muted detail beneath. The detail
 *  colour is keyed to the tooltip's own surface (dark text on the light dark-mode
 *  tooltip), not the app's muted token — which would be light-on-light there. */
export const TwoLineTip: React.FC<{ title: string; detail?: string }> = ({ title, detail }) => (
  <span className="flex flex-col gap-0.5">
    <span className="font-medium">{title}</span>
    {detail && <span className="text-gray-400 dark:text-gray-600">{detail}</span>}
  </span>
);
