import React from 'react';
import { LucideIcon, PanelLeft, Settings } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Tooltip, TooltipTrigger, TooltipContent } from '../ui/tooltip';
import { SELECTED_ITEM_BG } from './sidebarTokens';

export interface SidebarItem {
  id: string;
  title: string;
  icon: LucideIcon;
  /**
   * Legacy per-item accent colour. No longer used by the redesigned sidebar
   * (items share a uniform token treatment); kept optional until App.tsx stops
   * supplying it.
   */
  color?: string;
}

export interface SidebarSection {
  id: string;
  title?: string;
  subtitle?: string;
  items: SidebarItem[];
  /**
   * `'bottom'` pins the section to the foot of the nav (just above the utility
   * rail) rather than stacking it top-down — used for the Execution section.
   */
  position?: 'top' | 'bottom';
}

/**
 * Shared className for the icon-only controls in the sidebar footer rail
 * (Collapse, Notifications, Settings, the theme control). A fixed 36px square so
 * they sit evenly whether the rail is horizontal (sidebar expanded) or stacked
 * vertically (sidebar collapsed). Recessed `text-subtle` at rest; `text-blue`
 * when the control's view is the active one.
 */
export function footerRailItemClassName(isActive = false): string {
  return cn(
    'flex h-9 w-9 flex-none items-center justify-center rounded-lg transition-colors',
    isActive
      ? 'text-blue'
      : 'text-subtle hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)] hover:text-foreground',
  );
}

/**
 * shadcn Tooltip wrapper for the icon-only footer rail controls. Side defaults
 * to `top` (the horizontal expanded rail); pass `right` when the sidebar is
 * collapsed and the rail stacks vertically against the left edge.
 */
export function RailTooltip({
  label,
  side = 'top',
  children,
}: {
  label: string;
  side?: 'top' | 'right' | 'bottom' | 'left';
  children: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent side={side}>{label}</TooltipContent>
    </Tooltip>
  );
}

interface SidebarProps {
  sections: SidebarSection[];
  selectedItemId: string | null;
  onItemSelect: (itemId: string) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
  /**
   * Optional content rendered immediately after a specific nav item
   * (e.g. starred repos under the Repos item). Hidden when the
   * sidebar is collapsed.
   */
  renderAfterItem?: (itemId: string) => React.ReactNode;
  /** When provided, a Settings control is rendered bottom-aligned above the collapse toggle. */
  onSettingsSelect?: () => void;
  /** Whether the bottom Settings control is the current selection. */
  isSettingsSelected?: boolean;
  /**
   * Right-aligned content in the brand/logo row (e.g. the PRO badge). Hidden
   * when the sidebar is collapsed.
   */
  headerAccessory?: React.ReactNode;
  /**
   * Footer-rail icon control rendered after Collapse (e.g. Notifications).
   * Provided by Layout so it can reach app context; styled with
   * footerRailItemClassName so it matches the rest of the rail.
   */
  footerNotifications?: React.ReactNode;
  /**
   * Footer-rail icon control rendered last, after Settings (the theme control).
   * Trails Settings so Collapse stays first — see the footer rail comment.
   */
  footerTheme?: React.ReactNode;
  /**
   * The nav item whose section is active but not itself selected — e.g. "Repos"
   * while viewing a repo detail page, where the selected (blue) treatment lives
   * on the repo sub-row. Rendered emphasised (medium weight, foreground) but
   * without the blue selected styling.
   */
  activeSectionItemId?: string | null;
}

export const Sidebar: React.FC<SidebarProps> = ({
  sections,
  selectedItemId,
  onItemSelect,
  isCollapsed,
  onToggleCollapse,
  renderAfterItem,
  onSettingsSelect,
  isSettingsSelected = false,
  activeSectionItemId = null,
  headerAccessory,
  footerNotifications,
  footerTheme,
}) => {
  const topSections = sections.filter((s) => s.position !== 'bottom');
  const bottomSections = sections.filter((s) => s.position === 'bottom');

  const renderSection = (section: SidebarSection) => (
    <div key={section.id}>
      {section.title && !isCollapsed && (
        <p className="eyebrow mb-2 px-2 text-[10px] text-subtle">{section.title}</p>
      )}
      {section.subtitle && !isCollapsed && (
        <p className="-mt-1 mb-2 px-2 text-[11px] text-muted-foreground">{section.subtitle}</p>
      )}
      <ul className="space-y-0.5">
        {section.items.map((item) => {
          const isSelected = selectedItemId === item.id;
          const isActiveSection = !isSelected && activeSectionItemId === item.id;
          return (
            <li key={item.id}>
              <button
                onClick={() => onItemSelect(item.id)}
                aria-current={isSelected ? 'page' : undefined}
                title={isCollapsed ? item.title : undefined}
                className={cn(
                  'flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2 text-left transition-colors',
                  isCollapsed && 'justify-center px-0',
                  isSelected && 'font-medium text-blue',
                  // Active section (a child page is open) — emphasised but not blue.
                  isActiveSection &&
                    'font-medium text-foreground hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)]',
                  !isSelected &&
                    !isActiveSection &&
                    'font-normal text-muted-foreground hover:bg-[color-mix(in_oklab,var(--ds-fg)_5%,transparent)] hover:text-foreground',
                )}
                style={isSelected ? { background: SELECTED_ITEM_BG } : undefined}
              >
                <item.icon className="h-4 w-4 flex-shrink-0" />
                {!isCollapsed && <span>{item.title}</span>}
              </button>
              {!isCollapsed && renderAfterItem?.(item.id)}
            </li>
          );
        })}
      </ul>
    </div>
  );

  return (
    <aside
      className={cn(
        'flex h-full shrink-0 flex-col border-r border-border transition-all duration-200',
        isCollapsed ? 'w-16' : 'w-60',
      )}
    >
      {/* Brand wordmark — accessory (e.g. PRO badge) right-aligned in this row. */}
      <div className={cn('flex h-16 items-center', isCollapsed ? 'justify-center px-0' : 'justify-between px-5')}>
        <div className="flex items-center gap-2.5">
          <span className="text-xl" aria-hidden="true">
            🧠
          </span>
          {!isCollapsed && (
            <span className="display bg-gradient-to-r from-pink to-blue bg-clip-text text-lg font-bold text-transparent">
              tiny brain
            </span>
          )}
        </div>
        {!isCollapsed && headerAccessory}
      </div>

      <nav
        className={cn(
          // flex column so bottom-pinned sections sink to the foot of the nav via
          // mt-auto. pt-1 (not py-4) so the first nav item sits on the same line
          // as the repo workspace's Plans/Fixes/Spikes stage rail.
          'flex flex-1 flex-col overflow-y-auto pb-4 pt-1 text-sm',
          isCollapsed ? 'px-2' : 'px-3',
        )}
      >
        <div className={cn(isCollapsed ? 'space-y-2' : 'space-y-7')}>{topSections.map(renderSection)}</div>
        {bottomSections.length > 0 && (
          <div
            data-testid="sidebar-bottom-sections"
            className={cn('mt-auto pt-7', isCollapsed ? 'space-y-2' : 'space-y-7')}
          >
            {bottomSections.map(renderSection)}
          </div>
        )}
      </nav>

      {/* Bottom utility rail — icon-only. Order: Collapse · Notifications ·
          Settings · Theme. Collapse leads deliberately: when the sidebar
          collapses the rail reflows from a horizontal row to a vertical stack,
          and keeping Collapse first leaves the toggle you just clicked at the
          same start position (left edge / top) rather than jumping. */}
      <div
        className={cn(
          'mt-auto border-t border-border p-3',
          isCollapsed ? 'flex flex-col items-center gap-1' : 'flex items-center justify-between gap-1',
        )}
      >
        <RailTooltip label="Collapse" side={isCollapsed ? 'right' : 'top'}>
          <button
            onClick={onToggleCollapse}
            aria-label="Toggle sidebar"
            className={footerRailItemClassName()}
          >
            <PanelLeft className="h-4 w-4" />
          </button>
        </RailTooltip>
        {footerNotifications}
        {onSettingsSelect && (
          <RailTooltip label="Settings" side={isCollapsed ? 'right' : 'top'}>
            <button
              onClick={onSettingsSelect}
              aria-current={isSettingsSelected ? 'page' : undefined}
              aria-label="Settings"
              className={footerRailItemClassName(isSettingsSelected)}
              style={isSettingsSelected ? { background: SELECTED_ITEM_BG } : undefined}
            >
              <Settings className="h-4 w-4" />
            </button>
          </RailTooltip>
        )}
        {footerTheme}
      </div>
    </aside>
  );
};
