import type { Fix } from '../types';
import type { WorktreeBranchRef } from '../components/worktree-branches';

/**
 * The branch(es) a fix's work lives on, each flagged with whether a live
 * worktree exists — the shared derivation behind both the FixCard sidebar
 * marker and the FixDetail header indicator (fix fixcard-status-ignores-worktree
 * Task 3), so the two surfaces can't drift.
 *
 * Keyed on the BRANCH (the stable identity) so the same physical worktree —
 * surfacing as both a task/source dir-name and a lattice branch ref — collapses
 * to one entry. Lattice refs are filtered to live worktrees (isWorktree) STRICTLY
 * AHEAD of the launch ref; explicit task/source worktrees surface regardless of
 * ahead-status so a fresh/undiverged worktree still shows.
 *
 * Live-run (`activeRun`) worktrees are NOT folded in here — that pre-commit badge
 * is a card-only affordance the caller layers on (FixCard) after this base.
 */
export function deriveFixWorktreeBranches(fix: Pick<Fix, 'sourceWorktree' | 'tasks'>): WorktreeBranchRef[] {
  const rank: Record<string, number> = { not_started: 0, in_progress: 1, completed: 2, superseded: 2 };
  const byBranch = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
  const add = (branch: string, hasWorktree: boolean, worktreeName?: string) => {
    const prev = byBranch.get(branch);
    byBranch.set(branch, {
      hasWorktree: (prev?.hasWorktree ?? false) || hasWorktree,
      worktreeName: prev?.worktreeName ?? worktreeName,
    });
  };

  if (fix.sourceWorktree) add(fix.sourceWorktree.branch, true, fix.sourceWorktree.name);
  for (const task of fix.tasks) {
    if (task.worktree) add(task.worktree.branch, true, task.worktree.name);
    const cells = task.statusByRef || [];
    const launchRank = rank[cells.find((c) => c.isLaunchRef)?.status ?? 'not_started'] ?? 0;
    for (const cell of cells) {
      if (cell.isLaunchRef || !cell.isWorktree) continue;
      if ((rank[cell.status] ?? 0) <= launchRank) continue;
      add(cell.ref, true); // lattice refs carry no dir name
    }
  }
  return [...byBranch].map(([branch, v]) => ({ branch, ...v }));
}
